  ('africana-studies/the-african-american-experience/black-power-and-after', 'africana-studies', 'africana-studies/the-african-american-experience', 'Black Power and After', 'black-power-and-after', '', 4, 1),
  ('africana-studies/the-african-american-experience/reconstruction', 'africana-studies', 'africana-studies/the-african-american-experience', 'Reconstruction', 'reconstruction', '', 1, 1),
  ('africana-studies/the-african-american-experience/slavery-in-america', 'africana-studies', 'africana-studies/the-african-american-experience', 'Slavery in America', 'slavery-in-america', '', 0, 1),
  ('africana-studies/the-african-american-experience/the-black-experience-since-1865', 'africana-studies', 'africana-studies/the-african-american-experience', 'The Black Experience since 1865', 'the-black-experience-since-1865', 'African American life from emancipation to now, as one arc: Reconstruction''s promise — citizenship, the vote, Black officeholders — and its violent overthrow; Jim Crow, disfranchisement, and lynching (Ida B. Wells''s crusade); the Great Migration and the making of Black urban America; the Harlem Renaissance; the Second World War and the Double V; the civil rights revolution and Black Power; the post-1968 turn — deindustrialization, the drug war, and mass incarceration (Alexander''s The New Jim Crow); Black culture''s global reach from the blues to hip-hop; Obama, Black Lives Matter, and the 1619 debates; and the persistent racial wealth gap and the reparations question (Coates).', 5, 1),
  ('africana-studies/the-african-american-experience/the-civil-rights-movement', 'africana-studies', 'africana-studies/the-african-american-experience', 'The Civil Rights Movement', 'the-civil-rights-movement', '', 3, 1),
