  ('education-and-learning/educational-psychology/special-needs', 'education-and-learning', 'education-and-learning/educational-psychology', 'special needs', 'special-needs', '', 2, 1),
  ('education-and-learning/learning-science/how-people-learn', 'education-and-learning', 'education-and-learning/learning-science', 'how people learn', 'how-people-learn', '', 0, 1),
  ('education-and-learning/learning-science/learning-and-memory', 'education-and-learning', 'education-and-learning/learning-science', 'Learning and Memory', 'learning-and-memory', 'How experience leaves a durable physical trace in the brain — and what that means for how to study. The engram from the remembered event down to the molecule; memory as distinct systems (working versus long-term; declarative versus procedural) and the patient H.M., who located consolidation in the hippocampus; Hebb''s rule and its embodiment in long-term potentiation (the NMDA receptor as coincidence detector); Kandel''s sea slug and the half-billion-year-old machinery it shares with us; consolidation, sleep, and replay; reconsolidation and why every recall rewrites the memory; place and grid cells; emotional (flashbulb) memory; forgetting as an active function; the prodigies and mnemonists — eidetic memory, the memory palace, Shereshevsky, and highly superior autobiographical memory; the engram found and edited with optogenetics; the clinical failures from amnesia to Alzheimer''s; and the applied science of studying — retrieval, spacing, interleaving, teaching to learn, and sleep.', 1, 1),
  ('education-and-learning/learning-science/motivation', 'education-and-learning', 'education-and-learning/learning-science', 'motivation', 'motivation', '', 2, 1),
  ('education-and-learning/pedagogy/assessment', 'education-and-learning', 'education-and-learning/pedagogy', 'assessment', 'assessment', '', 3, 1),
  ('education-and-learning/pedagogy/lesson-design', 'education-and-learning', 'education-and-learning/pedagogy', 'lesson design', 'lesson-design', '', 2, 1),
  ('education-and-learning/pedagogy/socratic-teaching-method', 'education-and-learning', 'education-and-learning/pedagogy', 'Socratic teaching method', 'socratic-teaching-method', 'Teaching by asking rather than telling: Socrates in Plato''s dialogues — the elenchus (cross-examination that exposes contradictions), aporia as productive puzzlement, and maieutics, the ''midwifery'' of drawing knowledge out (the slave-boy geometry lesson in the Meno); Socratic irony and the stance of knowing that one does not know; the method''s modern descendants — the Socratic seminar and Paideia model in schools, the law-school case method from Langdell onward; what the research says about questioning, dialogue, and active learning; the critiques — intimidation versus inquiry, and when the method works or fails; and the original cautionary tale: Athens put Socrates to death for his questions.', 1, 1),
