  ('finance/alternative-investments/commodities-and-natural-resources', 'finance', 'finance/alternative-investments', 'Commodities and Natural Resources', 'commodities-and-natural-resources', '', 4, 1),
  ('finance/alternative-investments/core-concepts', 'finance', 'finance/alternative-investments', 'Core Concepts', 'core-concepts', 'What counts as an alternative investment and how it differs from traditional stocks and bonds; the main categories (private equity, hedge funds, real estate, commodities, infrastructure); and the case for holding them — diversification and the potential for higher returns, weighed against illiquidity, higher fees, leverage, and valuation difficulty.', 0, 1),
  ('finance/alternative-investments/hedge-funds', 'finance', 'finance/alternative-investments', 'Hedge Funds', 'hedge-funds', '', 2, 1),
  ('finance/alternative-investments/infrastructure', 'finance', 'finance/alternative-investments', 'Infrastructure', 'infrastructure', '', 5, 1),
  ('finance/alternative-investments/private-equity', 'finance', 'finance/alternative-investments', 'Private Equity', 'private-equity', '', 1, 1),
  ('finance/alternative-investments/real-estate', 'finance', 'finance/alternative-investments', 'Real Estate', 'real-estate', '', 3, 1),
  ('finance/corporate-issuers/capital-structure-and-leverage', 'finance', 'finance/corporate-issuers', 'Capital Structure and Leverage', 'capital-structure-and-leverage', 'How companies make use of leverage — financing with debt alongside equity — and the benefits and risks of doing so.', 4, 1),
  ('finance/corporate-issuers/core-concepts', 'finance', 'finance/corporate-issuers', 'Core Concepts', 'core-concepts', 'What a corporate issuer is, the main forms of business organization, and how companies raise and allocate capital; and the key players — shareholders, the board, management, creditors, and other stakeholders.', 0, 1),
  ('finance/corporate-issuers/corporate-governance', 'finance', 'finance/corporate-issuers', 'Corporate Governance', 'corporate-governance', 'Corporate governance — the system of controls and incentives that directs a company; the conflicts of interest among managers, shareholders, and other stakeholders, the mechanisms that manage them, and their risks and benefits.', 2, 1),
  ('finance/corporate-issuers/esg-considerations-in-investing', 'finance', 'finance/corporate-issuers', 'ESG Considerations in Investing', 'esg-considerations-in-investing', 'How environmental and social considerations are integrated into investing (ESG), and why they matter to both issuers and investors.', 3, 1),
  ('finance/corporate-issuers/stakeholder-management', 'finance', 'finance/corporate-issuers', 'Stakeholder Management', 'stakeholder-management', 'Identifying a company''s stakeholders (shareholders, creditors, employees, customers, suppliers, regulators, and the community) and managing their sometimes-competing interests.', 1, 1),
  ('finance/corporate-issuers/working-capital-and-liquidity', 'finance', 'finance/corporate-issuers', 'Working Capital and Liquidity', 'working-capital-and-liquidity', 'How companies manage working capital and liquidity to meet short-term operational needs.', 5, 1),
  ('finance/derivatives/arbitrage-and-replication', 'finance', 'finance/derivatives', 'Arbitrage and Replication', 'arbitrage-and-replication', 'Arbitrage — a riskless profit from mispricing — and how replicating a derivative''s payoff with the underlying plus cash enforces its price under the no-arbitrage condition.', 4, 1),
  ('finance/derivatives/contingent-claims-options', 'finance', 'finance/derivatives', 'Contingent Claims (Options)', 'contingent-claims-options', 'Options as contingent claims — the right, but not the obligation, to buy (call) or sell (put) an underlying; their payoffs and basic uses.', 3, 1),
  ('finance/derivatives/core-concepts', 'finance', 'finance/derivatives', 'Core Concepts', 'core-concepts', 'What a derivative is and how derivative markets work; the two families — forward commitments (forwards, futures, swaps) and contingent claims (options) — and the benefits and risks of using them.', 0, 1),
  ('finance/derivatives/forwards-and-futures', 'finance', 'finance/derivatives', 'Forwards and Futures', 'forwards-and-futures', 'Forward and futures contracts lock in a price today for a transaction later; how futures differ from forwards (exchange-traded, standardized, marked to market daily).', 1, 1),
  ('finance/derivatives/pricing-derivatives-from-the-underlying', 'finance', 'finance/derivatives', 'Pricing Derivatives from the Underlying', 'pricing-derivatives-from-the-underlying', 'Why a derivative''s price is tied to the price of its underlying asset, using arbitrage, replication, and the cost of carry.', 5, 1),
  ('finance/derivatives/swaps', 'finance', 'finance/derivatives', 'Swaps', 'swaps', 'Swaps as a series of forward commitments to exchange cash flows over time, such as interest rate swaps.', 2, 1),
  ('finance/equity-investments/characteristics-of-equity-securities', 'finance', 'finance/equity-investments', 'Characteristics of Equity Securities', 'characteristics-of-equity-securities', 'What equity investments are — ownership shares in a company — and their main types and features: common vs preferred stock, voting and ownership rights, and dividends, and how they differ across companies and markets.', 0, 1),
  ('finance/equity-investments/equity-valuation-models', 'finance', 'finance/equity-investments', 'Equity Valuation Models', 'equity-valuation-models', 'Basic equity valuation models: present-value / dividend discount models, multiplier (multiples) models, and asset-based valuation.', 3, 1),
  ('finance/equity-investments/global-equities', 'finance', 'finance/equity-investments', 'Global Equities', 'global-equities', 'Investing in equities around the world, and how global equity diversification supports longer-term growth and diversification objectives, in exchange for higher volatility than bonds.', 4, 1),
  ('finance/equity-investments/industry-and-company-analysis', 'finance', 'finance/equity-investments', 'Industry and Company Analysis', 'industry-and-company-analysis', 'How to analyze an industry and an individual company — competitive position, business model, and value drivers — in order to evaluate an equity security.', 2, 1),
  ('finance/equity-investments/security-markets-and-indexes', 'finance', 'finance/equity-investments', 'Security Markets and Indexes', 'security-markets-and-indexes', 'How security markets are organized, and how security market indexes are constructed, weighted, and used to measure and benchmark market performance.', 1, 1),
  ('finance/ethics-and-professional-standards/a-framework-for-ethical-decision-making', 'finance', 'finance/ethics-and-professional-standards', 'A Framework for Ethical Decision-Making', 'a-framework-for-ethical-decision-making', 'A structured, repeatable process for working through ethical dilemmas: identify the issue and stakeholders, weigh options and consequences, decide, act, and reflect.', 2, 1),
  ('finance/ethics-and-professional-standards/challenges-to-ethical-behavior', 'finance', 'finance/ethics-and-professional-standards', 'Challenges to Ethical Behavior', 'challenges-to-ethical-behavior', 'Why even well-intentioned people act unethically — situational pressures, incentives, overconfidence, and the gap between how we expect to behave and how we actually do.', 1, 1),
  ('finance/ethics-and-professional-standards/industry-standards-of-conduct', 'finance', 'finance/ethics-and-professional-standards', 'Industry Standards of Conduct', 'industry-standards-of-conduct', 'The standards of professional conduct that govern behavior in the investment industry, and how they guide real day-to-day decisions.', 3, 1),
  ('finance/ethics-and-professional-standards/the-role-of-ethics-and-professionalism', 'finance', 'finance/ethics-and-professional-standards', 'The Role of Ethics and Professionalism', 'the-role-of-ethics-and-professionalism', 'Why ethics and professionalism are central to the investment industry: how trust underpins the profession, how ethical conduct differs from merely legal conduct, and what professionalism demands of practitioners.', 0, 1),
  ('finance/finance-and-capital-markets/financial-statements', 'finance', 'finance/finance-and-capital-markets', 'financial statements', 'financial-statements', '', 2, 1),
  ('finance/finance-and-capital-markets/funds-and-investment-vehicles', 'finance', 'finance/finance-and-capital-markets', 'funds & investment vehicles', 'funds-and-investment-vehicles', '', 1, 1),
  ('finance/finance-and-capital-markets/housing-and-mortgages', 'finance', 'finance/finance-and-capital-markets', 'housing & mortgages', 'housing-and-mortgages', '', 3, 1),
  ('finance/finance-and-capital-markets/stocks-and-bonds', 'finance', 'finance/finance-and-capital-markets', 'stocks & bonds', 'stocks-and-bonds', '', 0, 1),
  ('finance/financial-statement-analysis/accounting-methods-and-their-effects', 'finance', 'finance/financial-statement-analysis', 'Accounting Methods and Their Effects', 'accounting-methods-and-their-effects', 'How alternative accounting methods and choices — revenue recognition, inventory, depreciation, and off-balance-sheet structures — change the picture the statements paint, and how this can be abused. Use the Enron scandal as the cautionary case: off-balance-sheet entities hid debt and inflated earnings until the company collapsed in 2001, taking auditor Arthur Andersen with it and prompting the Sarbanes-Oxley Act.', 4, 1),
  ('finance/financial-statement-analysis/financial-reporting-procedures', 'finance', 'finance/financial-statement-analysis', 'Financial Reporting Procedures', 'financial-reporting-procedures', 'How economic transactions flow through the accounting system to become financial statements: the reporting process, the accounting equation, and accrual accounting.', 2, 1),
  ('finance/financial-statement-analysis/financial-reporting-standards-and-disclosures', 'finance', 'finance/financial-statement-analysis', 'Financial Reporting Standards and Disclosures', 'financial-reporting-standards-and-disclosures', 'The standards that govern financial reporting and disclosure (such as IFRS and US GAAP), why they exist, and how required disclosures let users compare companies and judge quality.', 3, 1),
  ('finance/financial-statement-analysis/introduction-and-analysis-framework', 'finance', 'finance/financial-statement-analysis', 'Introduction and Analysis Framework', 'introduction-and-analysis-framework', 'A general framework for conducting financial statement analysis: what it sets out to answer, the steps from gathering data to drawing conclusions, and how analysts use the statements to judge a company''s performance, health, and prospects.', 0, 1),
  ('finance/financial-statement-analysis/primary-financial-statements', 'finance', 'finance/financial-statement-analysis', 'Primary Financial Statements', 'primary-financial-statements', 'The primary financial statements — the income statement, the balance sheet, the statement of cash flows, and the statement of changes in equity — what each one shows and how they link together.', 1, 1),
  ('finance/fixed-income/fixed-income-markets', 'finance', 'finance/fixed-income', 'Fixed-Income Markets', 'fixed-income-markets', 'How fixed-income markets are organized: who issues bonds (governments, corporations, agencies), how they are sold and traded, and the main market sectors and instruments.', 1, 1),
  ('finance/fixed-income/fixed-income-securities', 'finance', 'finance/fixed-income', 'Fixed-Income Securities', 'fixed-income-securities', 'What fixed-income securities are — bonds and other debt instruments — and their key features: issuer, maturity, coupon, principal, seniority, covenants, and embedded options.', 0, 1),
  ('finance/fixed-income/introduction-to-credit-analysis', 'finance', 'finance/fixed-income', 'Introduction to Credit Analysis', 'introduction-to-credit-analysis', 'The basic principles of credit analysis — assessing a borrower''s ability and willingness to repay, credit ratings, and yield spreads — illustrated with real defaults and downgrades such as the 2011 US credit-rating downgrade and the Greek and Argentine debt crises.', 6, 1),
  ('finance/fixed-income/risk-factors', 'finance', 'finance/fixed-income', 'Risk Factors', 'risk-factors', 'The main risks of holding bonds — interest rate risk (measured by duration and convexity), credit risk, liquidity risk, and inflation risk — and how they interact. Ground interest rate risk in real episodes such as Paul Volcker''s Fed rate hikes around 1980 and the sharp 2022 bond selloff.', 4, 1),
  ('finance/fixed-income/securitization-and-asset-backed-securities', 'finance', 'finance/fixed-income', 'Securitization and Asset-Backed Securities', 'securitization-and-asset-backed-securities', 'How pools of loans (mortgages, auto loans, credit-card receivables) are packaged into tradable securities — ABS, MBS, and CDOs. Anchor it in the 2007–2008 subprime mortgage crisis, when mispriced mortgage-backed securities and CDOs helped trigger a global financial crisis.', 5, 1),
  ('finance/fixed-income/valuation-of-fixed-income-securities', 'finance', 'finance/fixed-income', 'Valuation of Fixed-Income Securities', 'valuation-of-fixed-income-securities', 'How to calculate the value (price) of a fixed-income security by discounting its expected cash flows, and the drivers of that value — market yields, credit spreads, and the shape of the yield curve.', 2, 1),
  ('finance/fixed-income/yield-measures-and-bond-returns', 'finance', 'finance/fixed-income', 'Yield Measures and Bond Returns', 'yield-measures-and-bond-returns', 'Yield measures (yield to maturity, current yield, spot and forward rates), how to calculate them, and the fundamentals of what drives a bond''s total return.', 3, 1),
  ('finance/portfolio-planning-and-wealth-management/investment-solutions', 'finance', 'finance/portfolio-planning-and-wealth-management', 'Investment Solutions', 'investment-solutions', 'The range of available investment solutions — from individual stocks and bonds to mutual funds, ETFs, separately managed accounts, and alternatives — and how each fits different investors'' needs and constraints.', 5, 1),
  ('finance/portfolio-planning-and-wealth-management/portfolio-management-overview', 'finance', 'finance/portfolio-planning-and-wealth-management', 'Portfolio Management Overview', 'portfolio-management-overview', 'The fundamentals of portfolio and risk management: why investors hold diversified portfolios rather than single assets, the portfolio approach to return and risk, and the steps of the portfolio management process.', 0, 1),
  ('finance/portfolio-planning-and-wealth-management/portfolio-planning-and-construction', 'finance', 'finance/portfolio-planning-and-wealth-management', 'Portfolio Planning and Construction', 'portfolio-planning-and-construction', 'Turning an investor''s goals and constraints into a real portfolio: the investment policy statement (IPS), risk tolerance and objectives, and strategic asset allocation.', 3, 1),
  ('finance/portfolio-planning-and-wealth-management/portfolio-risk-and-return', 'finance', 'finance/portfolio-planning-and-wealth-management', 'Portfolio Risk and Return', 'portfolio-risk-and-return', 'The trade-off between risk and return, how diversification reduces risk, and the efficient frontier. How the capital asset pricing model (CAPM) prices risk and is used to identify the optimal level of risk in a portfolio (the tangency/market portfolio and the security market line).', 2, 1),
  ('finance/portfolio-planning-and-wealth-management/retail-vs-institutional-investors', 'finance', 'finance/portfolio-planning-and-wealth-management', 'Retail vs Institutional Investors', 'retail-vs-institutional-investors', 'The basics — a retail (individual) investor manages their own or their household''s money; an institutional investor (pension funds, endowments, insurers, sovereign wealth funds, mutual and hedge funds) invests large pools on behalf of others. How their goals, time horizons, resources, and interests diverge — vividly illustrated by the January 2021 GameStop short squeeze, when retail investors coordinating on Reddit''s r/WallStreetBets drove the stock up and squeezed institutional hedge funds (such as Melvin Capital) that had shorted it.', 4, 1),
  ('finance/portfolio-planning-and-wealth-management/return-and-risk-measurement', 'finance', 'finance/portfolio-planning-and-wealth-management', 'Return and Risk Measurement', 'return-and-risk-measurement', 'How to measure a portfolio''s return and its risk — expected return, variance and standard deviation — and how combining assets changes overall risk through diversification and correlation.', 1, 1),
  ('finance/quantitative-foundations/portfolio-mathematics', 'finance', 'finance/quantitative-foundations', 'Portfolio Mathematics', 'portfolio-mathematics', 'How the returns and risks of individual assets combine into the return and risk of a whole portfolio.', 4, 1),
  ('finance/quantitative-foundations/probability-trees-and-conditional-expectations', 'finance', 'finance/quantitative-foundations', 'Probability Trees and Conditional Expectations', 'probability-trees-and-conditional-expectations', 'Using probability to reason about uncertain outcomes, form expectations, and update beliefs as new information arrives.', 3, 1),
  ('finance/quantitative-foundations/rates-and-returns', 'finance', 'finance/quantitative-foundations', 'Rates and Returns', 'rates-and-returns', 'How interest rates and investment returns are defined and measured — the building blocks for comparing any investment.', 0, 1),
  ('finance/quantitative-foundations/statistical-measures-of-asset-returns', 'finance', 'finance/quantitative-foundations', 'Statistical Measures of Asset Returns', 'statistical-measures-of-asset-returns', 'How to summarize the distribution of asset returns — its center, spread, shape, and how returns move together.', 2, 1),
  ('finance/quantitative-foundations/the-time-value-of-money-in-finance', 'finance', 'finance/quantitative-foundations', 'The Time Value of Money in Finance', 'the-time-value-of-money-in-finance', 'Why a dollar today is worth more than a dollar tomorrow, and how to move cash flows through time to value them.', 1, 1),
  ('finance/statistical-methods/estimation-and-inference', 'finance', 'finance/statistical-methods', 'Estimation and Inference', 'estimation-and-inference', 'How to draw conclusions about a whole population from a sample, and how sample means behave.', 0, 1),
  ('finance/statistical-methods/hypothesis-testing', 'finance', 'finance/statistical-methods', 'Hypothesis Testing', 'hypothesis-testing', 'A formal procedure for using sample evidence to accept or reject a claim about a population.', 1, 1),
  ('finance/statistical-methods/introduction-to-big-data-techniques', 'finance', 'finance/statistical-methods', 'Introduction to Big Data Techniques', 'introduction-to-big-data-techniques', 'How large, fast, and varied data — and fintech tools — are transforming financial analysis.', 5, 1),
  ('finance/statistical-methods/introduction-to-linear-regression', 'finance', 'finance/statistical-methods', 'Introduction to Linear Regression', 'introduction-to-linear-regression', 'Fitting a straight line to describe how one variable depends on another, then judging how well it fits.', 4, 1),
  ('finance/statistical-methods/parametric-and-non-parametric-tests-of-independence', 'finance', 'finance/statistical-methods', 'Parametric and Non-Parametric Tests of Independence', 'parametric-and-non-parametric-tests-of-independence', 'Testing whether two variables move together, using correlation-based and rank/frequency-based methods.', 2, 1),
  ('finance/statistical-methods/simulation-methods', 'finance', 'finance/statistical-methods', 'Simulation Methods', 'simulation-methods', 'Modelling uncertain outcomes by generating many random scenarios instead of solving in closed form.', 3, 1),
