  ('geography/cartography-and-gis/maps', 'geography', 'geography/cartography-and-gis', 'maps', 'maps', '', 0, 1),
  ('geography/cartography-and-gis/remote-sensing', 'geography', 'geography/cartography-and-gis', 'remote sensing', 'remote-sensing', '', 2, 1),
  ('geography/cartography-and-gis/spatial-data', 'geography', 'geography/cartography-and-gis', 'spatial data', 'spatial-data', '', 1, 1),
  ('geography/economic-geography/development', 'geography', 'geography/economic-geography', 'development', 'development', '', 2, 1),
  ('geography/economic-geography/globalization', 'geography', 'geography/economic-geography', 'globalization', 'globalization', '', 3, 1),
  ('geography/economic-geography/resources', 'geography', 'geography/economic-geography', 'resources', 'resources', '', 0, 1),
  ('geography/economic-geography/trade', 'geography', 'geography/economic-geography', 'trade', 'trade', '', 1, 1),
  ('geography/human-geography/culture', 'geography', 'geography/human-geography', 'culture', 'culture', '', 3, 1),
  ('geography/human-geography/migration', 'geography', 'geography/human-geography', 'migration', 'migration', '', 1, 1),
  ('geography/human-geography/population', 'geography', 'geography/human-geography', 'population', 'population', '', 0, 1),
  ('geography/human-geography/urbanization', 'geography', 'geography/human-geography', 'urbanization', 'urbanization', '', 2, 1),
  ('geography/physical-geography/climate', 'geography', 'geography/physical-geography', 'climate', 'climate', '', 1, 1),
  ('geography/physical-geography/ecosystems', 'geography', 'geography/physical-geography', 'ecosystems', 'ecosystems', '', 2, 1),
  ('geography/physical-geography/hydrology', 'geography', 'geography/physical-geography', 'hydrology', 'hydrology', '', 3, 1),
  ('geography/physical-geography/landforms', 'geography', 'geography/physical-geography', 'landforms', 'landforms', '', 0, 1),
  ('geography/regional-geography/continents', 'geography', 'geography/regional-geography', 'continents', 'continents', '', 0, 1),
  ('geography/regional-geography/countries', 'geography', 'geography/regional-geography', 'countries', 'countries', '', 1, 1),
  ('geography/regional-geography/regional-studies', 'geography', 'geography/regional-geography', 'regional studies', 'regional-studies', '', 2, 1),
  ('history/20th-century-history/collapse-of-the-soviet-union-and-eastern-europe-the-end-of-the-cold-war', 'history', 'history/20th-century-history', 'Collapse of the Soviet Union and Eastern Europe: the End of the Cold War', 'collapse-of-the-soviet-union-and-eastern-europe-the-end-of-the-cold-war', 'How the communist world came apart, 1985–1991: Gorbachev''s glasnost and perestroika and the renunciation of the Brezhnev Doctrine; Poland — Solidarity, the Round Table, and the June 1989 elections; Hungary opens the border; the fall of the Berlin Wall (9 November 1989); Czechoslovakia''s Velvet Revolution and the violent end of Ceaușescu''s Romania; German reunification (1990); the Baltic drive for independence; the August 1991 coup, Yeltsin, and the dissolution of the USSR that December; shock therapy and the post-communist transitions; NATO and EU enlargement; and Yugoslavia''s violent breakup as the era''s dark counterpoint.', 8, 1),
  ('history/20th-century-history/european-decolonization', 'history', 'history/20th-century-history', 'European decolonization', 'european-decolonization', 'The end of the European empires after 1945: India and Pakistan''s independence and Partition (1947); Indonesia; Indochina and Dien Bien Phu (1954); the Suez crisis (1956) as the end of imperial pretension; Ghana (1957) and the African wave of 1960; the Algerian War (1954–62); the Congo crisis and Lumumba; the late Portuguese decolonizations (1974–75); Bandung (1955), non-alignment, and Third World solidarity; the theorists — Fanon, Nkrumah''s neocolonialism; and the contested legacies: borders, the Commonwealth, Françafrique, and the debates over empire''s balance sheet.', 9, 1),
  ('history/20th-century-history/france-under-nazi-occupation', 'history', 'history/20th-century-history', 'France Under Nazi Occupation', 'france-under-nazi-occupation', 'The dark years, 1940–1944: the collapse of 1940 and the armistice; Vichy — Pétain''s National Revolution, Laval, and collaboration d''État; the Statut des Juifs and the Vél d''Hiv roundup (1942), French complicity in deportation; the Milice; daily life — rationing, the démarcation line, the STO labor draft; resistance — de Gaulle''s appeal of 18 June, Jean Moulin and unification, the maquis; liberation and the épuration; and the memory wars — the resistance myth, Paxton''s revolution in the historiography, and the trials of Barbie, Touvier, and Papon.', 4, 1),
  ('history/20th-century-history/global-cold-war-and-the-arms-race', 'history', 'history/20th-century-history', 'Global Cold War and the Arms Race', 'global-cold-war-and-the-arms-race', 'The US-Soviet confrontation that organized the world, 1945–1991 — the postwar order, the liberation of Europe''s former colonies, and the violent and economic upheavals of the global Cold War: the order built after 1945 (the UN, Bretton Woods, the division of Europe) from Yalta to the Iron Curtain; the diplomatic legacy of the two world wars — Versailles''s cautionary lessons, wartime summitry, and the architecture designed to prevent a third; containment (Kennan), the Truman Doctrine, and the Marshall Plan; the Berlin blockade and the Wall; NATO and the Warsaw Pact; the nuclear arms race — from the Manhattan Project and Hiroshima to the H-bomb, ICBMs, Sputnik, and mutual assured destruction — and its treaties (the Test Ban, SALT and ABM, INF, START) alongside proliferation; the major crises of the Cold War era — the Berlin crises, Suez and Hungary (1956), the Cuban Missile Crisis (1962), Prague (1968), the Euromissiles and Able Archer (1983); the role of diplomacy in preserving peace between the two nuclear superpowers — the Moscow-Washington hotline, summitry from Geneva to Reykjavik, and arms-control negotiation as statecraft; the hot wars in Korea and Vietnam; the Cold War in the Global South — Westad''s ''global Cold War'' of interventions in Angola, Afghanistan, and Latin America; the Sino-Soviet split and Nixon in China; détente and its collapse; Reagan, Gorbachev, the fall of the Berlin Wall (1989), and the disintegration of the Soviet Union (1991); and the making of the post-Cold War world order — unipolarity, NATO and EU enlargement, and the argument over how the peace was won and how it was squandered.', 6, 1),
  ('history/20th-century-history/hitler-and-the-death-of-democracy-in-germany-1918-1945', 'history', 'history/20th-century-history', 'Hitler and the Death of Democracy in Germany, 1918-1945', 'hitler-and-the-death-of-democracy-in-germany-1918-1945', 'How a democracy died: Weimar''s birth in defeat and revolution (1918–19) and its structural fragilities — Versailles''s shadow, Article 48, fractured parties; the crises of 1923 (hyperinflation, the Beer Hall Putsch) and 1929; Hitler''s road to power — Mein Kampf, the Nazi electoral surge of 1930–32, and the backroom deal of 30 January 1933; the Machtergreifung — the Reichstag fire, the Enabling Act, Gleichschaltung, the Night of the Long Knives; the Third Reich''s mix of terror and consent — the Nuremberg Laws, propaganda, rearmament; the road to war and genocide; and 1945''s reckoning — with Weimar''s lessons for democratic fragility ever since.', 2, 1),
  ('history/20th-century-history/maoism', 'history', 'history/20th-century-history', 'Maoism', 'maoism', 'Mao''s remaking of Marxism and its world career: the sinification of Marxism — peasant revolution, the Yan''an way, the mass line, and continuous revolution; Maoism in power — collectivization, the Great Leap Forward and its famine, the Cultural Revolution; the cult — the Little Red Book, the badge and the poster; global Maoism (Lovell) — India''s Naxalites, Peru''s Shining Path, Nepal''s Maoists, the Khmer Rouge''s dark variant, and the Western intellectuals of the 1960s-70s; and the afterlife — Maoism''s ambiguous place in Deng''s and Xi''s China.', 13, 1),
  ('history/20th-century-history/partition-and-its-consequences-ireland-india-palestine', 'history', 'history/20th-century-history', 'Partition and its Consequences: Ireland, India, Palestine', 'partition-and-its-consequences-ireland-india-palestine', 'The partitions of Ireland, India, and Palestine at the moment of British decolonization — partition as the empire''s exit strategy, three times over: Ireland (1920–22) — the border, civil war, and the long road to the Troubles and the Good Friday Agreement; India (1947) — Mountbatten''s timetable, the Radcliffe line, up to fifteen million displaced and perhaps a million dead in Punjab and Bengal, and Kashmir''s unresolved fate; Palestine (1947–48) — the UN partition plan, the war, and the Nakba; the comparative questions — minorities and borders drawn in haste, population transfer as ''solution'', violence at the moment of imperial withdrawal; and why all three partitions remain politically alive today.', 12, 1),
  ('history/20th-century-history/power-and-protest-in-the-long-1960s-the-may-1968-movement', 'history', 'history/20th-century-history', 'Power and Protest in the Long 1960s: the May 1968 Movement', 'power-and-protest-in-the-long-1960s-the-may-1968-movement', 'Power and protest in the long 1960s — the year the postwar order shook: France in May–June 1968 — the student revolt from Nanterre to the Sorbonne, the barricades of the Latin Quarter, the general strike of some ten million workers, de Gaulle''s vanishing act and return, the Grenelle accords, and the June elections; and the global 1968 around it — the Prague Spring and its crushing, Mexico''s Tlatelolco massacre, the American upheavals (Tet, King''s assassination, Columbia, the Chicago DNC), the West German and Italian movements; plus the long cultural afterlife: the New Left, second-wave feminism, environmentalism, and the endless argument over what 1968 changed.', 11, 1),
  ('history/20th-century-history/the-cultural-revolution', 'history', 'history/20th-century-history', 'The Cultural Revolution', 'the-cultural-revolution', 'China''s decade of upheaval (1966–1976): Mao''s motives after the Great Leap disaster; the Red Guards, big-character posters, and struggle sessions; smashing the ''Four Olds'' and the assault on teachers, intellectuals, and heritage; the fall of Liu Shaoqi and Deng Xiaoping; violence, factional civil war, and the army''s restoration of order; the sent-down youth; the Lin Biao affair (1971); the Gang of Four and the end in 1976; the human toll and the 1981 party resolution — and how memory of the decade is managed and suppressed in China today.', 14, 1),
  ('history/20th-century-history/the-holocaust', 'history', 'history/20th-century-history', 'The Holocaust', 'the-holocaust', 'The Holocaust — ''the systematic, state-sponsored persecution and murder of six million Jews by the Nazi regime and its allies and collaborators,'' in the US Holocaust Memorial Museum''s definition — with each element of that definition unpacked: historical antisemitism from medieval Europe to modern racial pseudo-science; the First World War and the stab-in-the-back myth; Weimar Germany and the Nazi rise to power; Hitler''s role in the Nazi dictatorship — and the intentionalist-functionalist debate about how the genocide was decided; the Nuremberg Laws (1935) and Kristallnacht (1938); ghettoization; the Einsatzgruppen killings in the occupied East; the Wannsee Conference (1942) and the machinery of the ''Final Solution''; Auschwitz-Birkenau, Treblinka, and the death camps; six million Jewish victims — and the persecution and murder of millions of people from other groups: Roma and Sinti, disabled people (the T4 program), Slavic peoples, Soviet prisoners of war, Black people in Nazi Germany, and gay, lesbian, bisexual, and transgender people (Paragraph 175, the pink triangle); Jewish responses to persecution — flight and the closing doors, hiding, spiritual resistance, the ghetto archives (Ringelblum), and armed revolt from the Warsaw Ghetto Uprising (1943) to Sobibor; the rescuers; the attitude of the Allied nations — the Evian Conference, the St. Louis turned away, immigration barriers, what was known and when, and the debate over bombing Auschwitz; liberation, the Nuremberg trials, and Raphael Lemkin''s word ''genocide''; and the politics of memory, testimony, and denial since.', 3, 1),
  ('history/20th-century-history/the-interwar-period', 'history', 'history/20th-century-history', 'The Interwar Period', 'the-interwar-period', 'The fragile years between the world wars (1918–1939): the punitive peace of Versailles and the wounded world it left; the Roaring Twenties and the Jazz Age against the ruins of Europe; hyperinflation, the fleeting stabilization, and then the Great Depression that began with the 1929 Crash; the crisis of liberal democracy and the rise of fascism and Nazism (Mussolini, Hitler) and Stalinism; the Spanish Civil War as the era''s rehearsal; the failure of the League of Nations, appeasement, and collective security; decolonization''s first stirrings (Gandhi, the Arab revolt); and the slide toward a second world war.', 1, 1),
  ('history/20th-century-history/the-soviet-union-history-of-the-soviet-empire', 'history', 'history/20th-century-history', 'The Soviet Union: History of the Soviet Empire', 'the-soviet-union-history-of-the-soviet-empire', 'The USSR from revolution to collapse (1917–1991): the February and October Revolutions, Lenin and the Bolsheviks, civil war and War Communism, the NEP; Stalin''s rule — collectivization and the famines (including the Holodomor), the Five-Year Plans, the Great Terror, and the Gulag; the Great Patriotic War (Stalingrad, the Eastern Front''s role in defeating Nazi Germany); superpower status in the Cold War — the nuclear arms race, Sputnik and the space race, the Warsaw Pact; Khrushchev''s de-Stalinization and thaw, the Brezhnev era of stagnation, and dissidents like Solzhenitsyn and Sakharov; Gorbachev''s glasnost and perestroika, the revolutions of 1989, and the dissolution of the USSR in 1991 — plus its contested legacy in Russia and the post-Soviet states.', 7, 1),
  ('history/20th-century-history/the-vietnam-war-the-american-war-in-vietnam', 'history', 'history/20th-century-history', 'The Vietnam War: the American War in Vietnam', 'the-vietnam-war-the-american-war-in-vietnam', 'Three decades of war in Vietnam and its American convulsion: French Indochina and the First Indochina War — Dien Bien Phu (1954), the Geneva Accords, and partition; Diem''s South and the National Liberation Front; the Gulf of Tonkin Resolution (1964) and Americanization — Rolling Thunder, search-and-destroy, the draft; the Tet Offensive (1968) as military defeat and political earthquake; My Lai; the antiwar movement, the media, and the credibility gap; Nixon''s Vietnamization, the secret wars in Cambodia and Laos, and the Pentagon Papers; the Paris Accords (1973) and the fall of Saigon (1975); the costs — some 58,000 Americans and up to three million Vietnamese dead, plus the boat people; and the long aftermath in both countries, from the ''Vietnam syndrome'' to the Memorial wall.', 10, 1),
  ('history/20th-century-history/the-yalta-conference', 'history', 'history/20th-century-history', 'The Yalta Conference', 'the-yalta-conference', 'The February 1945 summit that sketched the postwar world: Roosevelt, Churchill, and Stalin at the Livadia Palace in Crimea; the agreements — the division of Germany into occupation zones and reparations, the Declaration on Liberated Europe and the promise of free elections in Poland, Soviet entry into the war against Japan in exchange for concessions in Asia, and the deal that made the United Nations possible (Security Council veto, founding conference at San Francisco); the context — the Red Army already held Eastern Europe, and FDR''s failing health; what followed — the broken promises in Poland, Potsdam, and the descent into Cold War; and the long argument over whether Yalta was realistic statecraft or a ''betrayal'' that conceded half of Europe.', 5, 1),
  ('history/20th-century-history/world-wars', 'history', 'history/20th-century-history', 'world wars', 'world-wars', '', 0, 1),
  ('history/ancient-civilizations/ancient-china-shang-zhou-and-the-hundred-schools', 'history', 'history/ancient-civilizations', 'Ancient China: Shang, Zhou, and the Hundred Schools', 'ancient-china-shang-zhou-and-the-hundred-schools', 'The formation of Chinese civilization (c. 1600–221 BCE): the Bronze Age Shang dynasty — oracle-bone divination and the birth of the Chinese writing system, ritual bronzes, and Anyang; the Zhou conquest and the Mandate of Heaven that would justify every later dynasty; the Western Zhou feudal order and its collapse into the Spring and Autumn and Warring States periods; the flowering of thought in that chaos — Confucius, Laozi, Mozi, and the Legalists (the Hundred Schools); iron, coinage, and mass infantry warfare; and the road to Qin''s unification in 221 BCE (which continues in Han History and Chinese History).', 3, 1),
  ('history/ancient-civilizations/ancient-egypt', 'history', 'history/ancient-civilizations', 'Ancient Egypt', 'ancient-egypt', 'Three thousand years of the Nile''s civilization: unification under Narmer (c. 3100 BCE) and the divine kingship of the pharaohs; the Old Kingdom and the pyramids of Giza; the Middle Kingdom; the New Kingdom''s imperial age — Hatshepsut, Akhenaten''s religious revolution, Tutankhamun, Ramesses II and Kadesh; religion and the afterlife — mummification, the Book of the Dead, the gods of the Egyptian pantheon; hieroglyphs, the Rosetta Stone, and Champollion''s decipherment; the Nile''s flood rhythm as the economy''s engine; Egypt in Africa — Nubia and the Kingdom of Kush, whose pharaohs ruled Egypt as the 25th Dynasty; the Late Period, the Ptolemies, and Cleopatra; and Egypt''s afterlives — Egyptology, Egyptomania, and the debate over the Africanness of Egypt, from Cheikh Anta Diop and the 1974 UNESCO Cairo symposium to Bernal''s Black Athena controversy.', 1, 1),
  ('history/ancient-civilizations/early-civilizations', 'history', 'history/ancient-civilizations', 'early civilizations', 'early-civilizations', '', 5, 1),
  ('history/ancient-civilizations/mesoamerican-cultures-olmec-maya-and-teotihuacan', 'history', 'history/ancient-civilizations', 'Mesoamerican Cultures: Olmec, Maya, and Teotihuacan', 'mesoamerican-cultures-olmec-maya-and-teotihuacan', 'The civilizations of ancient Mexico and Central America before the Aztecs (c. 1500 BCE–900 CE): the Olmec ''mother culture'' and its colossal heads; the shared Mesoamerican world — maize agriculture, the 260-day and 365-day calendars, the ballgame, pyramids, and bloodletting ritual; Teotihuacan, the great planned metropolis of the Avenue of the Dead; and above all the Maya — city-states like Tikal and Palenque, the only fully developed writing system of the pre-Columbian Americas, Long Count astronomy and mathematics (including zero), and the ''collapse'' of the southern lowlands. Sets up Moctezuma''s Mexico and the Aztec world that the Spanish met.', 4, 1),
  ('history/ancient-civilizations/mesopotamia', 'history', 'history/ancient-civilizations', 'Mesopotamia', 'mesopotamia', '', 0, 1),
  ('history/ancient-civilizations/the-indus-valley-civilization', 'history', 'history/ancient-civilizations', 'The Indus Valley Civilization', 'the-indus-valley-civilization', 'One of the world''s first urban civilizations (c. 3300–1300 BCE): the sophisticated cities of Harappa and Mohenjo-daro along the Indus and Ghaggar-Hakra rivers — grid-planned streets, the Great Bath, standardized fired-brick construction, covered drainage, and weights; a vast trade network reaching Mesopotamia (the Meluhha of cuneiform texts); the still-undeciphered Indus script and the enigmatic seals; the absence of clear palaces, temples, or royal tombs and the debate over how it was governed; the eclipse of the cities around 1900 BCE (climate change, river shifts, and the end of the Aryan-invasion theory in favor of gradual transformation); and its place in the deep history of South Asia.', 2, 1),
  ('history/classical-antiquity/ancient-greece', 'history', 'history/classical-antiquity', 'Ancient Greece', 'ancient-greece', '', 0, 1),
  ('history/classical-antiquity/rome-and-the-ancient-roman-world', 'history', 'history/classical-antiquity', 'Rome and the Ancient Roman World', 'rome-and-the-ancient-roman-world', 'From city-state to world empire: the republic and its institutions — SPQR, consuls, senate, tribunes; the Punic Wars and Hannibal; the republic''s collapse — the Gracchi, Marius and Sulla, Caesar and the crossing of the Rubicon; Augustus and the principate; the Pax Romana and the empire at its height — roads, aqueducts, concrete, cities from Britain to Syria; Roman law from the Twelve Tables to Justinian''s codification; slavery, spectacle, and the gladiators; women and the family; the rise of Christianity from persecution to Constantine; and the crisis of the third century opening onto the empire''s fall (continued in The Fall of the Roman Empire).', 1, 1),
  ('history/classical-antiquity/the-fall-of-the-roman-empire', 'history', 'history/classical-antiquity', 'The Fall of the Roman Empire', 'the-fall-of-the-roman-empire', 'Why the ancient world''s superpower came apart: the Crisis of the Third Century; Diocletian''s and Constantine''s reorganizations and the East-West division; pressure on the frontiers — the Goths'' victory at Adrianople (378), Alaric''s sack of Rome (410), the Vandal sack (455), and Attila''s Huns; the deposition of Romulus Augustulus by Odoacer in 476; why the Eastern empire endured another thousand years; and the great debate over causes — Gibbon''s classic account, overextension, plague and economic decline, the Christianity thesis, and the modern argument between ''transformation'' (Peter Brown''s late antiquity) and ''catastrophe'' (Bryan Ward-Perkins).', 2, 1),
  ('history/classical-antiquity/the-persian-empire', 'history', 'history/classical-antiquity', 'The Persian Empire', 'the-persian-empire', 'The first world empire (c. 550–330 BCE) and its successors: Cyrus the Great''s Achaemenid conquests and the famous tolerance of the Cyrus Cylinder; Darius I — the satrapy system, the Royal Road, the coinage, and Persepolis; Zoroastrianism; the Greco-Persian Wars (Marathon, Thermopylae, Salamis) seen from the Persian side rather than through Herodotus alone; Alexander''s conquest and the burning of Persepolis; and the later Iranian empires that carried the tradition — the Parthians who fought Rome and the Sasanians, Rome''s and then Byzantium''s great rival, down to the Arab conquest.', 3, 1),
  ('history/contemporary-history/china-today-the-economic-miracle-and-infrastructural-revolution', 'history', 'history/contemporary-history', 'China Today: the Economic Miracle and Infrastructural Revolution', 'china-today-the-economic-miracle-and-infrastructural-revolution', 'The Chinese economic miracle of the past 40 years and its monumental infrastructural revolution: Deng''s reform and opening (1978), the Special Economic Zones — Shenzhen from fishing village to megacity — WTO accession, and the largest poverty reduction in history; the country''s modern and extensive infrastructure — the world''s largest dams (Three Gorges and its 1.3 million displaced), the South-North Water Transfer, the world''s largest high-speed railway network built almost from scratch after 2008, expressways, the great ports, and gleaming new cities housing hundreds of millions of new urbanites (and the ''ghost city'' debate); how it was built — state capacity, five-year plans, state-owned enterprises, and land-finance; the Belt and Road as the model exported; the costs — environmental damage, debt, displacement; and the open question of whether the miracle can continue amid demographic decline, the property crisis, and rivalry with the United States.', 5, 1),
  ('history/contemporary-history/globalization', 'history', 'history/contemporary-history', 'Globalization', 'globalization', 'The making of an interconnected world and the fierce argument about it: the deep history — the Silk Roads, the Columbian exchange, and the first globalization of 1870–1914 — and the post-1945 acceleration through Bretton Woods, container shipping, and free-trade agreements; the hyper-globalization after 1990 — the WTO, global supply chains, offshoring, and the internet; who won and who lost — the rise of China and the emptying of Western factory towns; the anti-globalization and fair-trade movements from Seattle (1999) on; financial contagion; and the backlash — Brexit, trade wars, and ''deglobalization'' — that now clouds its future.', 2, 1),
  ('history/contemporary-history/modern-conflicts-since-1991', 'history', 'history/contemporary-history', 'Modern Conflicts since 1991', 'modern-conflicts-since-1991', 'War and violence since the Cold War: the Gulf War (1991) and the ''new world order''; the wars of the Yugoslav breakup and the Srebrenica genocide; the Rwandan genocide (1994); the September 11 attacks and the long wars in Afghanistan and Iraq; the rise and fall of ISIS; the Arab Spring and its aftermath, including the Syrian civil war; insurgency, drones, and the changing character of war; Russia''s wars in Georgia, Crimea, and the full-scale invasion of Ukraine (2022); and the humanitarian, refugee, and great-power stakes that make these conflicts the leading edge of contemporary history.', 4, 1),
  ('history/contemporary-history/technological-advancements-and-the-digital-age', 'history', 'history/contemporary-history', 'Technological Advancements and the Digital Age', 'technological-advancements-and-the-digital-age', 'How the digital revolution remade the world (1945–present): from ENIAC and the transistor to the integrated circuit and Moore''s Law; the ARPANET, the internet, and the World Wide Web; the personal computer, the smartphone, and social media; the platform giants and the surveillance-and-attention economy; the biotech revolution from the double helix to CRISPR and mRNA vaccines; artificial intelligence from symbolic AI to deep learning and large language models; and the debates that now define the age — privacy, misinformation, automation and work, and who governs the technologies reshaping human life.', 3, 1),
  ('history/contemporary-history/the-neoliberal-age', 'history', 'history/contemporary-history', 'The Neoliberal Age', 'the-neoliberal-age', 'The market revolution of our times: the 1970s crisis of the postwar Keynesian order — stagflation, the oil shocks, the end of Bretton Woods; the intellectual insurgency from Mont Pèlerin to Hayek and Friedman; the Volcker shock; Thatcher and Reagan — privatization, deregulation, tax cuts, and the defeats of the miners and PATCO; the Washington Consensus and structural adjustment in the Global South; the third way of Clinton and Blair; financialization and rising inequality; the 2008 crisis and the age''s contested afterlife — populist backlash, industrial policy''s return, and the debate (Gerstle) over whether the neoliberal order has ended.', 1, 1),
  ('history/contemporary-history/the-post-cold-war-era', 'history', 'history/contemporary-history', 'The Post-Cold War Era', 'the-post-cold-war-era', 'The world after 1991: the ''unipolar moment'' and American primacy; Fukuyama''s ''end of history'' against Huntington''s ''clash of civilizations''; the wars of the Yugoslav breakup and the Rwandan genocide as the decade''s dark answer to liberal optimism; the expansion of NATO and the EU eastward; the deepening of globalization and the rise of China and India; the September 11 attacks and the ''war on terror'' that reshaped the 2000s; the 2008 financial crisis; the return of great-power competition, populism, and authoritarianism; and the pandemic, climate, and AI pressures defining the present.', 0, 1),
  ('history/early-modern-period/colonial-america', 'history', 'history/early-modern-period', 'Colonial America', 'colonial-america', 'The founding and growth of Britain''s mainland American colonies (1607–1763): Jamestown, tobacco, and the terrible early years; Plymouth, the Puritans, and the ''city upon a hill''; the very different colonial worlds — the plantation South and the entrenchment of racial slavery, the middle colonies'' diversity, New England''s towns; relations with Native nations from trade to war (the Pequot War, King Philip''s War); indentured servitude, Bacon''s Rebellion, and the Salem trials; the Atlantic economy and the consumer revolution; the Great Awakening and colonial self-government; and the aftermath of the Seven Years'' War that set the stage for revolution.', 5, 1),
  ('history/early-modern-period/declarations-of-independence-the-american-revolution', 'history', 'history/early-modern-period', 'Declarations of Independence: the American Revolution', 'declarations-of-independence-the-american-revolution', 'How thirteen colonies became a republic (1763–1789), starting from the causes: the constitutional, legal, economic, social, and political issues that prompted the imperial crisis after the Seven Years'' War and resulted in the colonies'' decision to break with Great Britain — parliamentary sovereignty versus colonial charters, taxation without representation, the Stamp Act, Townshend duties, the Boston Massacre and Tea Party, and the Coercive Acts; Lexington and Concord, Bunker Hill, and the Continental Congresses; Paine''s Common Sense and the Declaration of Independence (July 4, 1776) — Jefferson''s draft and the political philosophy of the Revolution: Locke''s natural rights and the right of revolution, republicanism and civic virtue, the historians'' argument between liberal and republican readings (Bailyn, Wood, Pocock), and the Declaration''s contradictions on slavery; the war itself — Washington''s army, Saratoga (1777) and the French alliance, Valley Forge, Yorktown (1781) and the Treaty of Paris (1783); how the Revolution affected people at all levels of society — the elite who occupied leadership roles, the regular citizens who mobilized for it, African Americans enslaved and free (Dunmore''s Proclamation, Black Patriots and Black Loyalists), Loyalists and their exile, women (the homespun boycotts, Abigail Adams''s ''Remember the Ladies''), Native nations, and immigrants; the Articles of Confederation, Shays''s Rebellion, and the Constitutional Convention of 1787; and the Declaration''s global afterlife as a template for later declarations of independence.', 10, 1),
  ('history/early-modern-period/french-and-haitian-revolutions', 'history', 'history/early-modern-period', 'French and Haitian Revolutions', 'french-and-haitian-revolutions', 'The intertwined revolutions that redefined liberty — and exposed its limits: France 1789 — the Estates-General, the Bastille, the Declaration of the Rights of Man, the radical Republic and the Terror (Robespierre), Thermidor, and Napoleon; Saint-Domingue 1791 — the great slave uprising, Toussaint Louverture, the 1794 abolition, Napoleon''s attempt to restore slavery, and Dessalines''s declaration of Haitian independence (1804), the first Black republic; how each revolution forced the other''s contradictions into the open (revolutionary universalism versus colonial slavery); Haiti''s crushing 1825 indemnity to France; and both revolutions'' global echoes through the Atlantic world and Latin America.', 9, 1),
  ('history/early-modern-period/ottoman-social-and-cultural-history', 'history', 'history/early-modern-period', 'Ottoman Social and Cultural History', 'ottoman-social-and-cultural-history', 'The Ottoman world from the inside: Istanbul''s neighborhoods, markets, and waterfront; the coffeehouse revolution and the state''s futile bans; the imperial harem and the ''sultanate of women'' (Peirce); guilds, janissary-artisans, and urban protest; the Sufi orders and popular religion; everyday life in the millets — Greek, Armenian, Jewish, and Arab provincial worlds; slavery as lived institution; the long delay and arrival of Ottoman print (Müteferrika, 1727); Tanzimat-era cultural transformation — newspapers, photography, the fez; and how social history revises the old decline narrative.', 7, 1),
  ('history/early-modern-period/revolutions', 'history', 'history/early-modern-period', 'revolutions', 'revolutions', 'Revolution as the engine of modern history: the Atlantic age of revolutions — American, French, Haitian, and the Spanish American independence wars (Bolívar, San Martín); 1848, the springtime of peoples, and its failures; the twentieth century''s great revolutions — Russian, Chinese, Cuban, Iranian; what makes a revolution and how they run — radicalization, terror, Thermidor, restoration; the theorists from Tocqueville to Arendt to Skocpol; and the word''s wider reach — industrial, scientific, and cultural revolutions — as a lens on transformative change.', 8, 1),
  ('history/early-modern-period/the-enlightenment', 'history', 'history/early-modern-period', 'The Enlightenment', 'the-enlightenment', 'The eighteenth century''s revolution in ideas: Locke and Newton as founding inspirations; the philosophes — Voltaire''s campaigns against fanaticism, Montesquieu''s separation of powers, Rousseau''s social contract, Diderot and d''Alembert''s Encyclopédie; Kant''s ''What is Enlightenment?'' (dare to know); the republic of letters — salons, coffeehouses, academies, and the women who ran the salons; the Scottish Enlightenment — Hume and Adam Smith; deism, toleration, and the critique of religious authority; enlightened absolutism (Frederick II, Catherine II, Joseph II); the movement''s blind spots on slavery, race, and gender; its imprint on the American and French Revolutions; and the counter-Enlightenment critique from Burke to today.', 0, 1),
  ('history/early-modern-period/the-mughal-empire', 'history', 'history/early-modern-period', 'The Mughal Empire', 'the-mughal-empire', 'India''s last great empire (1526–1857), studied alongside its peers — the Mughal, British, and late Ottoman empires as the classic comparative set: Babur''s conquest and the Timurid inheritance; Akbar''s synthesis — sulh-i kul (peace with all), the Rajput alliances, the mansabdari system, and the din-i ilahi experiment; the imperial workshop — Persianate court culture, miniature painting, and the architecture from Fatehpur Sikri to Shah Jahan''s Taj Mahal; the economy that made it the world''s manufacturing giant; Aurangzeb — expansion, the jizya''s return, and the contested reputation; the eighteenth-century decline and the successor states; the Company''s shadow empire and the last emperor''s exile after 1857; and the Mughal legacy fought over in Indian politics today.', 3, 1),
  ('history/early-modern-period/the-ottomans', 'history', 'history/early-modern-period', 'The Ottomans', 'the-ottomans', 'The empire that bridged three continents for six centuries (c. 1299–1922), beginning with the emergence of the Ottoman state from a frontier principality into a world empire in its social, political, and cultural dimensions: pre-Ottoman Anatolia — the Seljuks, the beyliks, and the post-Mongol vacuum; frontier (gazi) society and its fluid Muslim-Christian world; methods of conquest — accommodation, vassalage, and istimalet as much as the sword; centralization and the institutionalization of power under Mehmed II; the land regime (timar) and the peasantry; urbanization and the remaking of conquered cities; intercommunal relations; religion and learning — the medreses and the ulema; architecture and literature from early Bursa to Sinan; and relations with Byzantium and the Islamic and European states throughout; then Mehmed II''s conquest of Constantinople (1453); Suleiman the Magnificent — lawgiver, Vienna (1529), and the empire''s classical age; the devshirme and the Janissaries; the millet system and religious pluralism; Lepanto (1571) and the contest for the Mediterranean; the second siege of Vienna (1683) and the long territorial retreat; the Tanzimat reforms and the ''sick man of Europe''; the Young Turks, the Balkan Wars, the First World War and the Armenian genocide; and the empire''s dissolution into Atatürk''s republic.', 6, 1),
  ('history/early-modern-period/the-rise-of-absolutism', 'history', 'history/early-modern-period', 'The Rise of Absolutism', 'the-rise-of-absolutism', 'The early modern state''s claim to total sovereignty: divine-right theory (Bodin, Bossuet, Hobbes''s Leviathan); Richelieu, Mazarin, and the Fronde; Louis XIV — Versailles, court society, standing armies, Colbert''s mercantilism, and the revocation of the Edict of Nantes; the military revolution and the fiscal-military state; Hohenzollern Prussia and the Great Elector; Peter the Great''s transformation of Russia; the Habsburgs; and the English exception — civil war, the execution of Charles I, and the Glorious Revolution of 1688 that entrenched parliamentary limits absolutism could not cross.', 2, 1),
  ('history/early-modern-period/the-scientific-revolution', 'history', 'history/early-modern-period', 'the Scientific Revolution', 'the-scientific-revolution', 'The remaking of knowledge itself (c. 1543–1727): Copernicus''s heliocentrism; Tycho''s observations and Kepler''s laws; Galileo — the telescope, mechanics, and the 1633 trial; Vesalius and Harvey in medicine; Bacon''s empiricism and Descartes''s mechanical philosophy; Newton''s Principia (1687) uniting heavens and earth; the new institutions — the Royal Society (1660) and the Académie des sciences — and instruments, experiment, and mathematization as method; alchemy, astrology, and religion entangled with the new science; and the revolution''s link forward to the Enlightenment and the debate over whether ''revolution'' is the right word.', 1, 1),
  ('history/early-modern-period/tokugawa-shogunate', 'history', 'history/early-modern-period', 'Tokugawa Shogunate', 'tokugawa-shogunate', 'Early modern Japan under the shoguns (1603–1868): Tokugawa Ieyasu''s victory at Sekigahara and the founding of the Edo bakufu; the alternate-attendance system that bound the daimyo, the rigid four-class order, and two and a half centuries of internal peace (the Pax Tokugawa); sakoku, the ''closed country'' policy, and the tiny Dutch window at Dejima; the growth of Edo into the world''s largest city, a vibrant merchant economy, and the floating-world culture of kabuki, ukiyo-e, and haiku; rural stress and rebellion; and the arrival of Commodore Perry''s black ships in 1853, which shattered the system and led into the Meiji Restoration.', 4, 1),
  ('history/medieval-history/byzantine-civilization-the-greek-tradition-300-1500', 'history', 'history/medieval-history', 'Byzantine Civilization: the Greek Tradition (300–1500)', 'byzantine-civilization-the-greek-tradition-300-1500', 'The Eastern Roman Empire and the Greek tradition it carried across twelve centuries, from late antiquity to the end of the Middle Ages (c. 300–1500) — including the identity question at its heart: a people who called themselves Romans (Romaioi), were labeled ''Greeks'' by the medieval West, and became ''Byzantine'' only through modern historians — what ''Roman'' and ''Greek'' actually meant to them (Kaldellis''s Romanland and the current debate): Constantine''s founding of Constantinople; Justinian and Theodora — the Corpus Juris Civilis, Hagia Sophia, and the attempted reconquest of the West; Greek fire and the Arab sieges; Iconoclasm; the Macedonian renaissance and Basil II; the conversion of the Slavs (Cyril and Methodius) and the Orthodox commonwealth; the Great Schism of 1054; Manzikert (1071) and the appeal that launched the Crusades; the Fourth Crusade''s sack of Constantinople (1204) and the Palaiologan twilight; the fall to Mehmed II in 1453; the society of the Eastern Roman Empire in the Middle Ages — Constantinopolitans and provincials, elites and people of lower social status: the court and the great families, but also peasants, artisans, merchants, soldiers, monks and nuns, women, and eunuchs, glimpsed through saints'' lives, letters, and the Book of the Eparch; the Greek intellectual and religious tradition throughout — the Cappadocian Fathers and Chrysostom, John of Damascus and iconophile theology, Photios and the copying that preserved classical Greek literature, Psellos, hesychasm and Gregory Palamas; and Byzantium''s legacy — Roman law, Orthodox Christianity, and the scholars and manuscripts (Plethon, Bessarion) that carried Greek learning to Renaissance Italy.', 1, 1),
  ('history/medieval-history/constantinople', 'history', 'history/medieval-history', 'Constantinople', 'constantinople', 'The city that was an empire''s argument: Byzantium refounded as Constantine''s New Rome (330); the Theodosian Walls that turned back a thousand years of sieges; Hagia Sophia and Justinian''s ''Solomon, I have outdone thee''; the Hippodrome, the factions, and the ceremonial city; the harbors, the Golden Horn''s chain, and the grain fleets; Greek fire against the Arab sieges; the city of relics and icons; 1204 — the Fourth Crusade''s sack and the Latin interlude; the Palaiologan twilight; 29 May 1453 — Mehmed II, the great cannon, and the fall; and the afterlives — Ottoman Kostantiniyye and Istanbul, and Constantinople as memory in the Orthodox world.', 7, 1),
  ('history/medieval-history/early-medieval-history', 'history', 'history/medieval-history', 'Early Medieval History', 'early-medieval-history', 'Europe and the Mediterranean from the fall of the Western Roman Empire (476) to about 1000: the barbarian successor kingdoms (Franks, Visigoths, Ostrogoths, Anglo-Saxons); Byzantium under Justinian and the survival of Roman law; the rise of Islam and the Arab conquests; the spread of Christianity and monasticism (Benedict, Irish and Anglo-Saxon missionaries); the Merovingians and Carolingians, Charlemagne''s coronation in 800 and the Carolingian Renaissance; the Treaty of Verdun (843); the Viking, Magyar, and Saracen invasions; and why historians now reject the label ''Dark Ages''.', 0, 1),
  ('history/medieval-history/feudalism', 'history', 'history/medieval-history', 'feudalism', 'feudalism', 'The web of lordship that organized medieval power: lords, vassals, fiefs, homage and fealty; knights, chivalry, and the castle; manorialism and serfdom as the economic base; the fragmentation of public authority after the Carolingians; the Church within feudal society; feudal monarchy and its slow reassertion (Domesday England, Capetian France); the system''s decline with money, towns, plague, and gunpowder states; and the historians'' quarrel — from Marc Bloch''s classic account to Elizabeth A. R. Brown''s and Susan Reynolds''s challenge to the very concept of ''feudalism''.', 2, 1),
  ('history/medieval-history/islamic-caliphate', 'history', 'history/medieval-history', 'Islamic Caliphate', 'islamic-caliphate', 'The institution that led the Islamic world for thirteen centuries: the succession to Muhammad (632) and the Rashidun caliphs; the Sunni-Shia split and Karbala (680); the Umayyads in Damascus and the conquests from Spain to Central Asia (Tours, 732); the Abbasids in Baghdad (762) and the House of Wisdom; rival caliphates in Córdoba and Fatimid Cairo; the Mongol sack of Baghdad (1258); the Ottoman claim to the caliphate; its abolition by Atatürk in 1924; and the caliphate as an idea in modern Islamic and Islamist politics.', 10, 1),
  ('history/medieval-history/islamic-golden-age', 'history', 'history/medieval-history', 'Islamic golden age', 'islamic-golden-age', '', 12, 1),
  ('history/medieval-history/medieval-islamic-commercial-revolution-800-1200-ce', 'history', 'history/medieval-history', 'Medieval Islamic Commercial Revolution (800-1200 CE)', 'medieval-islamic-commercial-revolution-800-1200-ce', 'The world''s first great commercial integration — a moment of globalization before globalization — centered on the Islamic lands from Baghdad to al-Andalus: the rise of new trade routes extending across land and sea to join the Mediterranean and the Indian Ocean, North and Sub-Saharan Africa, Central and South Asia; the development of novel commercial and financial institutions — the suftaja (bill of exchange), sakk (cheque), qirad/commenda investment partnerships, and funduq caravanserais; gold dinars and silver dirhams as world currencies (found from Scandinavia to China); the merchants who brought about this historic transformation — the merchant diasporas and partnerships glimpsed in the Cairo Geniza''s extraordinary record of Jewish and Muslim traders (Goitein); the commodities — textiles, paper (which spread from Samarkand westward), spices, slaves, gold; the forms of labor and investment that undergirded this transformation — caravan porters, sailors, enslaved labor, and pooled merchant capital; market institutions, hisba regulation, and Islamic commercial law; the urban boom of Baghdad, Cairo, and Córdoba; and the debate over how this commercial revolution prefigured — and shaped — Europe''s later one.', 11, 1),
  ('history/medieval-history/political-debates-in-the-empire-of-new-rome', 'history', 'history/medieval-history', 'Political Debates in the Empire of New Rome', 'political-debates-in-the-empire-of-new-rome', 'Political thought and argument in Byzantium, the Empire of New Rome: Constantinople as New Rome and the imperial ideology built on it — Eusebius''s Christian kingship, taxis (order) and oikonomia (accommodation); how far the empire remained a republic of the Romans (Kaldellis''s monarchy-versus-republic debate); the people''s politics — the circus factions and the Nika riot (532); iconoclasm as the empire''s greatest political-theological argument; emperor and patriarch — symphonia and its breakdowns (Chrysostom''s exile, the Photian schism); court rhetoric, advice literature, and panegyric as political speech; and the late debates — union with Rome versus Orthodox integrity, and Plethon''s radical Hellenism on the eve of 1453.', 8, 1),
  ('history/medieval-history/sex-love-and-marriage-in-the-middle-ages', 'history', 'history/medieval-history', 'Sex, Love, and Marriage in the Middle Ages', 'sex-love-and-marriage-in-the-middle-ages', 'Intimacy under God''s law: how the Church made marriage — the consent doctrine, indissolubility, and Fourth Lateran''s rules; clerical celibacy and its enforcement; courtly love from the troubadours to the romances, and the debate over what it really was; the great lovers — Abelard and Heloise''s letters; women''s voices — Margery Kempe''s negotiated celibacy, Christine de Pizan; peasant versus noble marriage — dowry, land, and strategy; the regulation of prostitution; medicine''s ideas about sex and reproduction; same-sex desire and the Boswell debate; annulment as medieval divorce; and how these medieval frameworks still echo in modern marriage.', 5, 1),
  ('history/medieval-history/slavery-in-the-global-middle-ages', 'history', 'history/medieval-history', 'Slavery in the global Middle Ages', 'slavery-in-the-global-middle-ages', 'Bondage between antiquity and the Atlantic system: the post-Roman slaveries of Europe and the Viking slave trade (Dublin''s markets, the routes to the east that gave ''Slav'' to ''slave''); the Mediterranean traffic of Venice, Genoa, and the Black Sea; the trans-Saharan, Red Sea, and Indian Ocean trades; military slavery and its paradoxes — the Mamluks who ruled Egypt, the Ottoman devshirme; slavery in law and religion — church, ulama, and the ransoming orders; the blurred line between serfdom and slavery; and how these medieval systems set patterns the Atlantic world would industrialize.', 9, 1),
  ('history/medieval-history/the-crusades', 'history', 'history/medieval-history', 'The Crusades', 'the-crusades', 'Two centuries of holy war and their long shadow: Urban II''s call at Clermont (1095); the First Crusade and the capture of Jerusalem (1099); the crusader states; Saladin, Hattin, and the Third Crusade with Richard the Lionheart (1187–92); the Fourth Crusade''s sack of Constantinople (1204); the military orders — Templars and Hospitallers; the wider crusading world (the Reconquista, the Baltic crusades); the fall of Acre (1291); and the consequences for Christian-Muslim-Jewish relations, trade, and historical memory down to today.', 6, 1),
  ('history/medieval-history/the-middle-ages-medieval-period', 'history', 'history/medieval-history', 'The Middle Ages (medieval period)', 'the-middle-ages-medieval-period', 'Europe c. 500–1500 as one arc: the early, high, and late medieval periods; manorialism and feudal bonds; the power of the Church — papacy, monasteries, the Investiture Controversy; the medieval agricultural revolution, the growth of towns, guilds, and universities; scholasticism (Aquinas); cathedrals and Gothic art; the Black Death (1347–51) and its social aftershocks; the Hundred Years'' War and peasant revolts; and the late-medieval crises that shaded into the Renaissance.', 4, 1),
  ('history/medieval-history/urban-institutions', 'history', 'history/medieval-history', 'urban institutions', 'urban-institutions', 'The medieval town as a laboratory of self-government: the revival of towns from the eleventh century; charters, communes, and the fight for autonomy; merchant and craft guilds — apprenticeship, quality control, monopoly; town councils, mayors, and citizenship (''town air makes free''); markets and fairs (Champagne) and the commercial revolution; the Hanseatic League; the Italian city-republics — Venice, Genoa, Florence; universities (Bologna, Paris, Oxford) as urban corporations; hospitals, confraternities, and cathedral-building; and how urban institutions incubated law, finance, and representative practices that outlived the Middle Ages.', 3, 1),
  ('history/modern-era-19th-century/british-empire', 'history', 'history/modern-era-19th-century', 'British Empire', 'british-empire', 'The empire on which the sun never set, c. 1600–1997: the first empire — Atlantic colonies, Caribbean sugar and slavery, Ireland — and its rupture with American independence (1783); the swing to the East — the East India Company, conquest of India, and the Raj after 1857; the settler dominions (Canada, Australia, New Zealand, South Africa) and responsible government; abolition (1807, 1833) alongside indentured labor; free-trade imperialism and the Victorian high noon — Victoria as Empress of India, the Scramble for Africa; the world wars as imperial wars and the empire''s overstretch; Indian independence and Partition (1947); Suez (1956); African decolonization; Hong Kong''s handover (1997); the Commonwealth; and the fierce ongoing debate over the empire''s balance sheet.', 1, 1),
  ('history/modern-era-19th-century/imperial-expansion-and-resistance', 'history', 'history/modern-era-19th-century', 'Imperial Expansion and Resistance', 'imperial-expansion-and-resistance', 'The New Imperialism and the peoples who fought it, c. 1850–1914: the Scramble for Africa and the Berlin Conference (1884–85); the British Raj after the Indian Rebellion of 1857; the technologies of conquest — steamships, quinine, the Maxim gun — and the ideologies (''civilizing mission'', social Darwinism); King Leopold''s Congo; resistance and its outcomes — Ethiopia''s victory at Adwa (1896), the Zulu and Ashanti wars, the Boxer Uprising, the Herero and Nama genocide, Maji Maji; the economics of empire and its critics (Hobson, Lenin); and how colonial resistance seeded the anticolonial nationalisms that would drive decolonization.', 2, 1),
  ('history/modern-era-19th-century/modern-china', 'history', 'history/modern-era-19th-century', 'Modern China', 'modern-china', 'China from the Opium Wars to superpower, pivoting on the revolutionary years of 1911, 1949, and 1978 — the empire''s fall, the Communist victory, and reform''s launch — and beginning with the decline of the Qing and the dramatic collapse of China''s imperial system in 1911 — the Opium Wars and the unequal treaties, the Taiping Rebellion, self-strengthening and its failure, the Hundred Days'' Reform, the Boxer Uprising, the New Policies that came too late, and the Wuchang uprising that ended two millennia of imperial rule; the 1911 Revolution and Sun Yat-sen; warlords, the May Fourth Movement, and the Nationalist-Communist struggle; the Japanese invasion and the Second Sino-Japanese War; 1949 and the People''s Republic; Mao''s rule — the Great Leap Forward famine and the Cultural Revolution; Deng Xiaoping''s reform and opening (1978); Tiananmen (1989); WTO accession (2001) and the rise to the world''s second economy; and the Xi Jinping era.', 7, 1),
  ('history/modern-era-19th-century/the-american-civil-war', 'history', 'history/modern-era-19th-century', 'The American Civil War', 'the-american-civil-war', 'The war that remade the United States (1861–1865): Union and Confederate resources, strategies, and leadership (Lincoln, Davis, Grant, Lee); Antietam and the Emancipation Proclamation; Gettysburg and Vicksburg (1863) as the turning point; Black soldiers and the USCT; total war and Sherman''s March; the home fronts, conscription, and dissent; Appomattox and Lincoln''s assassination; some 750,000 dead; the 13th–15th Amendments and the stakes of Reconstruction; and the memory wars — emancipationist memory versus the ''Lost Cause''.', 4, 1),
  ('history/modern-era-19th-century/the-coming-of-the-civil-war', 'history', 'history/modern-era-19th-century', 'The Coming of the Civil War', 'the-coming-of-the-civil-war', 'How slavery broke the American union, 1820–1861: the Missouri Compromise; nullification; the Mexican War and the Wilmot Proviso; the Compromise of 1850 and the Fugitive Slave Act; Uncle Tom''s Cabin and Northern opinion; the Kansas-Nebraska Act (1854), Bleeding Kansas, and the birth of the Republican Party; the caning of Sumner; Dred Scott (1857); the Lincoln-Douglas debates; John Brown''s raid on Harpers Ferry (1859); Lincoln''s election (1860); secession, the Confederacy, and Fort Sumter.', 3, 1),
  ('history/modern-era-19th-century/the-meiji-restoration', 'history', 'history/modern-era-19th-century', 'The Meiji Restoration', 'the-meiji-restoration', 'Japan''s rush to modernity (1868–1912): the overthrow of the Tokugawa shogunate and the restoration of imperial rule under the Meiji Emperor; the slogan ''rich country, strong army'' (fukoku kyohei); the abolition of the samurai class, the Iwakura Mission''s study of the West, and the wholesale importing of railways, industry, a conscript army, and a Prussian-style constitution; rapid industrialization and the zaibatsu; victory over China (1895) and Russia (1905) — the first modern defeat of a European power by an Asian state; and the tensions of headlong Westernization that would shape imperial Japan into the twentieth century.', 5, 1),
  ('history/modern-era-19th-century/the-opium-wars', 'history', 'history/modern-era-19th-century', 'The Opium Wars', 'the-opium-wars', 'How Britain broke China in the nineteenth century. The problem: the British East India Company faced a China that had everything Britain wanted — tea, silk, porcelain — but wanted almost nothing in return, so the trade deficit was hemorrhaging British silver into the Qing treasury. For a century silver flowed in only one direction — out of Europe and into China — and by the late 1700s Britain was running out of cash. The solution: opium. The East India Company grew the drug in India and, rather than smuggle it itself, auctioned it at Calcutta to private ''country traders'' who carried it into China through Canton (Guangzhou), the empire''s richest port and the one place foreigners could trade. That structure was deliberate: it gave the British government plausible deniability — the Company''s opium monopoly reaped the profits while the illegal smuggling was, on paper, someone else''s crime. It turned the flow of silver around. In just over a century the trade exploded from a mere 200 chests a year to a staggering 40,000 — a chest being the standard shipping crate of the trade, roughly 63–65 kg (about 140 lbs) of processed opium each, so 40,000 chests meant thousands of tons of the drug pouring in annually. By the 1830s the whole flow had reversed: now it was China hemorrhaging silver to Britain. On the order of 12 million addicts, and the metal that paid for the drug drained the empire. The British treasury swelled; China collapsed under the weight of a deflated currency — as silver left the country its value against the copper coins ordinary people used soared, so taxes and debts (reckoned in silver) effectively doubled, ruining the peasantry and gutting the state''s revenue — even as millions died of opium addiction itself. The drug supply chain was run by the most powerful empire on earth. The reckoning: the Daoguang Emperor ordered Commissioner Lin Zexu to shut it all down; in 1839 Lin seized and destroyed some 1,000 tons of opium at Humen and wrote his famous open letter to Queen Victoria demanding Britain stop the trade (''By what right do they … use the poisonous drug to injure the Chinese people?''). Britain answered with warships. Give the Parliamentary vote its own beat, because it was extraordinarily close: in the House of Commons debate of April 1840 the government carried the day by just nine votes, 271 to 262 — a swing of only five members would have reversed it, and one of the most aggressive imperial wars in history might never have been launched. The debate was a masterclass in moral gymnastics: supporters went to great lengths to avoid the word ''opium'', reframing the war as a matter of ''national honour'' and the defence of British ''private property'' that China had ''seized'' — conveniently ignoring that the property was a drug, illegal in London itself. The opposition, led by William Ewart Gladstone (a future Prime Minister), called out the hypocrisy directly, denouncing ''a war more unjust in its origin, a war more calculated in its progress to cover this country with permanent disgrace, I do not know and I have not read of'' (real Hansard quotation — do not alter it). But the vast profits and tax revenue of the opium trade prevailed. Include an image at this point — a depiction of the Commons/Parliament or {{image: William Ewart Gladstone | William Ewart Gladstone, who denounced the war as a national disgrace}}. Then the war itself exposed the technological gulf the Industrial Revolution had opened: the iron paddle-steamer Nemesis — a shallow-draught gunboat that seemed to Chinese observers a ''devil ship'' that could not be burned or sunk and moved against wind and tide — devastated the war-junks (convey the shock it caused, but do NOT invent a Chinese quotation about it; quote only a genuinely verifiable source, and omit a quote rather than fabricate one). Note the chronology carefully and correctly: Lin Zexu was recalled in disgrace and exiled to Ili in Xinjiang in the autumn of 1840, BEFORE the Nemesis''s famous actions of 1841 — so the commissioner never witnessed them; the emperor made him the scapegoat for a war his firmness had helped trigger. In May 1841 Canton bought off a British assault with a ransom of six million silver dollars. The First Opium War (1839–1842) and the Treaty of Nanjing — the first of the ''unequal treaties'' — ceded Hong Kong, opened the treaty ports, imposed indemnities and extraterritoriality; the Second Opium War (1856–1860) ended with British and French troops burning the Old Summer Palace. This is the opening of China''s ''century of humiliation,'' a wound that still shapes Chinese nationalism today. GIVE Lin Zexu''s 1839 open letter to Queen Victoria its own short section, headed and set apart: introduce who wrote it and why, quote two or three genuine translated passages as a Markdown blockquote (the famous moral appeal — that opium is banned in Britain itself, so Britain has no right to inflict it on China; ''By what right do they … use the poisonous drug to injure the Chinese people?''), and note that the letter almost certainly never reached the Queen. This is a real, published primary source (the standard Teng & Fairbank translation) — quote it faithfully and never invent or embellish wording; if unsure of exact phrasing, quote the shortest passage you are confident is accurate. Then read the letter closely: the most striking thing is not its politeness but its appeal to the monarch''s conscience — Lin cast opium as a ''moral poison'' that harmed everyone''s long-term interests, and argued from Confucian logic, the assumption that a virtuous ruler naturally suppresses what is evil. But he was addressing a mercantilist empire that measured ''good'' by the profit it booked, not by virtue. The letter therefore reads as a collision of two incompatible moral universes — Confucian statecraft against the profit-calculus of empire — and it was doomed: the British government, trapped by the sheer scale of the opium revenue, had effectively forfeited morality to it. Place an image beside the letter — {{image: Lin Zexu | Commissioner Lin Zexu, ordered by the Daoguang Emperor to end the opium trade}}. Continues in Modern China.', 6, 1),
  ('history/modern-era-19th-century/the-victorian-era', 'history', 'history/modern-era-19th-century', 'The Victorian Era', 'the-victorian-era', 'Britain and its world at the zenith of empire (1837–1901): Queen Victoria as the age''s symbol; industrial and urban transformation and its social costs — the world Dickens, Engels, and the sanitary reformers described; the expansion of the franchise, the rise of the middle class, and the cult of respectability, domesticity, and ''separate spheres''; the crisis of faith between Darwin and religion; the high noon of the British Empire and the scramble for Africa; poverty, public health, and reform (factory acts, the workhouse); and the science, literature, and moral earnestness — and hypocrisy — that gave the era its name.', 0, 1),
  ('history/regional-histories/africa', 'history', 'history/regional-histories', 'Africa', 'africa', '', 2, 1),
  ('history/regional-histories/americas', 'history', 'history/regional-histories', 'Americas', 'americas', '', 3, 1),
  ('history/regional-histories/asia', 'history', 'history/regional-histories', 'Asia', 'asia', '', 1, 1),
  ('history/regional-histories/europe', 'history', 'history/regional-histories', 'Europe', 'europe', '', 0, 1),
  ('history/regional-histories/middle-east', 'history', 'history/regional-histories', 'Middle East', 'middle-east', '', 4, 1),
  ('history/regional-histories/the-settler-revolution-at-the-edge-of-empire-australia-1770-1901', 'history', 'history/regional-histories', 'The ''Settler Revolution'' at the Edge of Empire: Australia, 1770-1901', 'the-settler-revolution-at-the-edge-of-empire-australia-1770-1901', 'Australia from Cook to Federation: James Cook''s 1770 charting and claim of the east coast; the doctrine of terra nullius; the First Fleet and the penal colony at Sydney Cove (1788) and the convict transportation system; frontier violence and the dispossession of Aboriginal peoples — epidemics, massacres, and resistance leaders like Pemulwuy; squatters, pastoral expansion, and the wool economy; the ''settler revolution'' (James Belich''s term) of explosive Anglo migration and boom-bust growth; the 1850s gold rushes and the Eureka Stockade (1854); colonial self-government; anti-Chinese agitation and the roots of White Australia; and the federation movement culminating in the Commonwealth of Australia on 1 January 1901 — with the century''s enduring consequences for Indigenous Australians.', 5, 1),
  ('history/renaissance-and-reformation/atlantic-slave-wars', 'history', 'history/renaissance-and-reformation', 'Atlantic Slave Wars', 'atlantic-slave-wars', 'The violence that made and unmade Atlantic slavery, c. 1500–1888: the transatlantic slave trade and the African wars and raiding that supplied it (Dahomey, Asante, the Kongo civil wars); the Middle Passage and shipboard revolts (the Amistad, 1839); maroon communities and their wars — Palmares in Brazil, Jamaica''s First and Second Maroon Wars; the great uprisings — Stono (1739), Tacky''s Revolt (1760), the Haitian Revolution (1791–1804, the only successful slave revolution, Toussaint Louverture), Demerara (1823), and the Baptist War in Jamaica (1831–32); how rebellion pushed abolition — Britain''s 1807 trade ban and 1833 emancipation, the Royal Navy''s suppression squadron; and emancipation''s long endgame through the US Civil War to Brazil in 1888.', 4, 1),
  ('history/renaissance-and-reformation/european-expansion-overseas-age-of-exploration', 'history', 'history/renaissance-and-reformation', 'European Expansion Overseas (Age of Exploration)', 'european-expansion-overseas-age-of-exploration', 'How Europe reached, mapped, and seized much of the globe (c. 1415–1600): motives — God, gold, and glory; Portuguese navigation down the African coast, Dias, and da Gama''s sea route to India; Columbus (1492) and the Treaty of Tordesillas (1494); Magellan''s circumnavigation; the conquests of the Aztec and Inca empires (Cortés, Pizarro) and why they succeeded — steel, horses, allies, and above all disease; Portugal''s trading-post empire in Asia; the Spanish colonial system; the Dutch and English East India companies; and the demographic catastrophe and global connections that expansion set in motion.', 2, 1),
  ('history/renaissance-and-reformation/new-world-economy', 'history', 'history/renaissance-and-reformation', 'new world economy', 'new-world-economy', 'How the encounter of hemispheres created the first global economy: the Columbian exchange of crops, animals, and diseases; Potosí and the silver flows that tied the Americas to Spain and China; the sugar revolution and the plantation complex; encomienda, coerced Indigenous labor, and the turn to African slavery; mercantilism, navigation acts, and the triangular trade; the Price Revolution in Europe; the commercial institutions born of Atlantic trade — joint-stock companies, marine insurance, the Amsterdam exchange; and how the New World economy transformed Europe, Africa, and the Americas alike.', 3, 1),
  ('history/renaissance-and-reformation/the-protestant-and-catholic-reformations', 'history', 'history/renaissance-and-reformation', 'The Protestant and Catholic Reformations', 'the-protestant-and-catholic-reformations', 'The shattering of Latin Christendom: Luther''s Ninety-five Theses (1517), justification by faith, and the printing press; Zwingli, the radical reformation, and Calvin''s Geneva; Henry VIII and the English Reformation; the Catholic (Counter-) Reformation — the Council of Trent, Ignatius Loyola and the Jesuits, the Roman Inquisition and the Index, baroque piety; the wars of religion — the Schmalkaldic War and the Peace of Augsburg, the French wars and St. Bartholomew''s Day (1572), the Dutch Revolt, and the Thirty Years'' War ending at Westphalia (1648); and the Reformations'' legacies for literacy, conscience, and the state.', 1, 1),
  ('history/renaissance-and-reformation/the-renaissance', 'history', 'history/renaissance-and-reformation', 'The Renaissance', 'the-renaissance', 'The rebirth that made the modern West''s self-image: humanism from Petrarch to civic humanism; Florence and Medici patronage; the artistic revolution — Brunelleschi''s dome and perspective, Donatello, Leonardo, Michelangelo, Raphael, Titian; Gutenberg''s printing press and the spread of learning; Machiavelli''s The Prince and new political thought; the Northern Renaissance — Erasmus, More, Dürer; women and the querelle des femmes; courts, diplomacy, and the Italian Wars; and the historiographical debate from Burckhardt''s ''discovery of the individual'' to modern revisions.', 0, 1),
  ('history/the-industrial-revolution/the-industrial-revolution', 'history', 'history/the-industrial-revolution', 'The Industrial Revolution', 'the-industrial-revolution', 'The transformation that made the modern world (c. 1760–1840): why it began in Britain — coal, capital, colonies, agricultural improvement, and useful knowledge; the breakthroughs in textiles (the spinning jenny, the water frame, the power loom) and the steam engine (Newcomen to Watt); the factory system and the new discipline of the clock; the human cost — child labor, the industrial city, and the world E. P. Thompson''s working class was made in; iron, canals, and then railways; and the runaway debate over living standards, the environment, and whether it was liberation or catastrophe. The great divergence that separated Western incomes from the rest.', 0, 1),
  ('history/the-industrial-revolution/the-second-industrial-revolution', 'history', 'history/the-industrial-revolution', 'The Second Industrial Revolution', 'the-second-industrial-revolution', 'The second wave of industrialization (c. 1870–1914): the shift from coal and iron to steel (Bessemer), electricity, chemicals, and the internal-combustion engine; the new science-based industries and the corporate research lab; mass production, the assembly line, and Taylorism; the railway and telegraph networks that knit continents and the steamship and undersea cable that knit the globe; the United States and Germany overtaking Britain; the rise of big business, finance capital, and the modern corporation; and the transformation of everyday life through electric light, the telephone, the automobile, and the department store.', 1, 1),
  ('history/thematic-history/abolitionist-women', 'history', 'history/thematic-history', 'Abolitionist Women', 'abolitionist-women', 'The women who drove the fight against slavery on both sides of the Atlantic: Britain''s pioneers — Elizabeth Heyrick''s call for immediate emancipation and the women-led sugar boycotts; America''s organizers and orators — the Grimké sisters, Lucretia Mott and the Philadelphia Female Anti-Slavery Society, Lydia Maria Child, and Maria Stewart; Black abolitionist women — Sojourner Truth (''Ain''t I a Woman?''), Harriet Tubman and the Underground Railroad, Frances Ellen Watkins Harper; Harriet Beecher Stowe and the impact of Uncle Tom''s Cabin (1852); the mass petition campaigns that made abolition a popular cause; and how exclusion — women barred from the 1840 World Anti-Slavery Convention — helped spark the women''s rights movement at Seneca Falls (1848).', 25, 1),
  ('history/thematic-history/ai-and-empire', 'history', 'history/thematic-history', 'AI and Empire', 'ai-and-empire', 'The relationship between AI and empire, read historically: computing''s imperial and military genealogy — Hollerith''s census machines, Bletchley Park, and the Cold War funding (DARPA, SAGE) that built the field; earlier ''tools of empire'' (Headrick''s telegraphs and railways) as the precedent; the material empire of AI — chips and the Taiwan chokepoint, export controls, rare earths, energy-hungry data centers, undersea cables; data colonialism and extraction (Couldry and Mejias, Crawford''s Atlas of AI) and the Global South labor of data labeling and content moderation; platform power and surveillance capitalism (Zuboff); AI nationalism and the US-China contest; algorithmic governance, facial recognition, and the export of surveillance; digital sovereignty movements and calls for decolonizing AI (Gebru and the AI-ethics dissidents); and whether AI concentrates power like the imperial technologies before it — or can be governed differently.', 15, 1),
  ('history/thematic-history/american-capitalism', 'history', 'history/thematic-history', 'American Capitalism', 'american-capitalism', 'The economic history of the United States as the history of its capitalism: colonial merchants and Hamilton''s financial program; the market revolution — canals, railroads, the telegraph; slavery''s cotton economy and the ''new history of capitalism'' debate; the corporation and the Gilded Age titans (Rockefeller, Carnegie, J.P. Morgan) and the antitrust response; Fordism and mass consumption; the Crash of 1929 and the New Deal''s remaking of the state-market bargain; the postwar boom and the consumer republic; deregulation and financialization from the 1970s; and Silicon Valley, venture capital, and the platform economy.', 5, 1),
  ('history/thematic-history/american-empire-the-rise-of-the-united-states-as-a-global-empire', 'history', 'history/thematic-history', 'American Empire: the Rise of the United States as a Global Empire', 'american-empire-the-rise-of-the-united-states-as-a-global-empire', 'How a settler republic became a global empire — and what that rise did to the planet: continental empire first — the Louisiana Purchase, the War of 1812 and the failed conquest of Canada, Indian removal and the wars of dispossession, the Mexican-American War (1846–48) and the cession that followed, and the filibusters'' illegal invasions of Cuba and Nicaragua in the 1850s (Narciso López''s expeditions, William Walker''s Nicaragua) as slavery''s expansionists went freelancing; 1898 and the overseas turn — Cuba, Puerto Rico, the Philippines and its brutal war, Hawai''i and Guam; the Panama Canal, dollar diplomacy, and interventions in Latin America; the Second World War, the ''empire of bases,'' Bretton Woods, and the Cold War national security state; the historians'' debate — formal versus informal empire, Williams''s ''empire as a way of life,'' ''empire by invitation.'' The same century saw profound transformations in natural ecologies worldwide — plantation economies (United Fruit), oil frontiers, the Green Revolution, nuclear testing in the Pacific, Agent Orange in Vietnam — and the answering rise of environmental movements, from conservation and Silent Spring to Earth Day, the EPA, environmental justice, and global environmentalism.', 16, 1),
  ('history/thematic-history/american-food', 'history', 'history/thematic-history', 'American Food', 'american-food', 'The United States told through what it eats: Indigenous foodways and the Three Sisters; the Columbian exchange on the plate; enslaved cooks and the African roots of Southern and soul food; immigrant kitchens — how Italian, Chinese, Mexican, and Jewish food became ''American''; industrialization — canning, refrigeration, the meatpacking exposés (Sinclair''s The Jungle) and the Pure Food and Drug Act (1906); the supermarket, the TV dinner, and the suburban kitchen; fast food''s empire — McDonald''s and the drive-thru nation; hunger and abundance — food stamps, food deserts, obesity; the counterculture''s whole-earth cooking, Julia Child, and farm-to-table (Alice Waters); and food as identity, region, and argument — barbecue''s borders and all.', 18, 1),
  ('history/thematic-history/borders-and-borderlands', 'history', 'history/thematic-history', 'Borders and Borderlands', 'borders-and-borderlands', 'How humanity drew its lines: from frontiers and marches to the surveyed boundary — natural-border myths, the cartographic state; the great line-drawings — the Berlin Conference''s Africa, Sykes-Picot, the Radcliffe line, the DMZ; passports and papers — the First World War watershed and the ''invention of the passport'' (Torpey); borderlands as worlds of their own — mixing, smuggling, and shifting identity (Sahlins, the US-Mexico borderlands school); walls from Hadrian to Berlin to today''s border fortifications; Schengen''s opening against the global hardening; and the border as industry, spectacle, and humanitarian crisis.', 9, 1),
  ('history/thematic-history/cryo-history-histories-of-cold-places', 'history', 'history/thematic-history', 'Cryo-History: Histories of Cold Places', 'cryo-history-histories-of-cold-places', 'The past read from ice: polar exploration and its dramas — Franklin''s lost expedition, Scott and Amundsen''s race, Shackleton''s Endurance; the Indigenous Arctic — Inuit, Sámi, and the knowledge that explorers borrowed and erased; ice cores as archives — how Greenland and Antarctic ice record volcanoes, lead pollution, and ten thousand years of climate; the cold rush — whaling, sealing, and fur; refrigeration''s revolution in food and cities (the cold chain); cryosphere geopolitics — the Antarctic Treaty (1959), Arctic sea routes and resources; and the melt itself as the great historical event of our time — permafrost, glaciers, and what their retreat exposes and unleashes.', 10, 1),
  ('history/thematic-history/digital-history', 'history', 'history/thematic-history', 'Digital History', 'digital-history', 'How computers and the internet changed the practice of history: the field''s roots in humanities computing and pioneers like Roy Rosenzweig; mass digitization of archives, newspapers, and books; distant reading and text mining of large corpora; GIS and spatial history; network analysis of correspondence and trade; databases and quantitative history; crowdsourced transcription projects (e.g. Transcribe Bentham); public history on the web and digital exhibits; born-digital sources and web archives as the historical record of our own era; and the methodological debates — what counts as an argument, sustainability of projects, and the limits of quantification.', 22, 1),
  ('history/thematic-history/economic', 'history', 'history/thematic-history', 'economic', 'economic', '', 0, 1),
  ('history/thematic-history/environmental-history', 'history', 'history/thematic-history', 'Environmental history', 'environmental-history', 'The story of human choices made within the constraints imposed by the non-human world: climate as an actor — the Little Ice Age, the seventeenth-century crisis, and today''s anthropogenic climate change and the Anthropocene debate; extinctions — from the megafauna to the passenger pigeon and the ongoing sixth extinction; invasive species and biological exchange — the Columbian exchange and Crosby''s ecological imperialism; energy as history''s motor — the transitions from wood and muscle to coal, oil, and the atom, and what each rearranged; disease environments (McNeill); deforestation, soils, and the Dust Bowl (Worster); regulation and the state — conservation versus preservation (Pinchot, Muir), national parks, the EPA, the Clean Air and Water Acts, and the Montreal Protocol; environmentalism from Silent Spring (1962) to Earth Day; and the field''s classics — Crosby, Worster, and Cronon''s Changes in the Land and Nature''s Metropolis.', 21, 1),
  ('history/thematic-history/global-history', 'history', 'history/thematic-history', 'Global History', 'global-history', 'History beyond the nation-state — the field and its methods: connections and comparisons across regions; world-systems theory (Wallerstein) and the Great Divergence debate (Pomeranz); commodities as global threads — Mintz''s sugar, Beckert''s cotton; oceans as units of analysis — Atlantic, Indian Ocean, Pacific worlds; mobilities — migration, disease, ideas; global microhistory and the biographies that cross empires; the critiques — Eurocentrism smuggled back in, the ''global'' that ignores the immobile (Adelman) — and what global history reveals that national histories cannot.', 8, 1),
  ('history/thematic-history/global-history-of-capitalism-past-present-future', 'history', 'history/thematic-history', 'Global History of Capitalism: Past, Present, Future', 'global-history-of-capitalism-past-present-future', 'Capitalism as a world system across five centuries: the transition to capitalism itself — enclosure, agrarian change, and the Brenner debate; merchant capitalism and the joint-stock revolution (the VOC, 1602); slavery and capitalism — the Atlantic economy''s role in early accumulation, from the Williams thesis to the new history of capitalism; the Industrial Revolution and factory capitalism, with class formation and class conflict at its heart (Thompson''s making of the working class, the strike waves and labor movements); industrialization and deindustrialization as one connected story — the factory''s rise in the North Atlantic and its migration to the Global South, the rust belts left behind; the labor capitalism doesn''t count — informal employment from street vendors to gig platforms, and unwaged reproductive labor (Federici and the wages-for-housework argument); the gold standard and the first globalization (1870–1914); collapse — world wars and the Great Depression; Bretton Woods (1944) and the embedded-liberal postwar boom; the 1970s crisis, the end of dollar-gold convertibility (1971), and the neoliberal turn (Thatcher, Reagan, the Washington Consensus); China''s reform era (1978) and global supply chains; the 2008 financial crisis; platform and digital capitalism; inequality and its critics (Piketty); and the contested future — climate change and the green transition, deglobalization, automation and AI — read through Smith, Marx, Keynes, Hayek, and Polanyi.', 17, 1),
  ('history/thematic-history/histories-of-emotions-from-the-rational-self-to-modern-neuroscience', 'history', 'history/thematic-history', 'Histories of Emotions: From the ''Rational Self'' to Modern Neuroscience', 'histories-of-emotions-from-the-rational-self-to-modern-neuroscience', 'Do feelings have a history? From the ''rational self'' of Enlightenment thought to modern neuroscience: Febvre''s call to write the history of sensibility; honor and shame societies; the eighteenth century''s cult of sensibility and public weeping; Victorian restraint and the stiff upper lip; fear, love, anger, and grief as they changed across time; the field''s tools — Stearns''s emotionology, Rosenwein''s emotional communities, Reddy''s emotives; emotional labor (Hochschild) and the management of feeling in modern capitalism; and the neuroscience turn — LeDoux, Damasio, and Barrett''s constructed emotion — in dialogue with history''s evidence that emotions are made, not merely given.', 11, 1),
  ('history/thematic-history/history-and-drugs', 'history', 'history/thematic-history', 'History and Drugs', 'history-and-drugs', 'Drugs and humans across the epochs — and the always-uneven line between medicine, vice, sacrament, and commodity, drawn again and again by whoever holds power: opium, alcohol, coca, and tobacco in the ancient world''s temples and medicine chests; the Columbian Exchange''s new intoxicants and the coca rations that kept Potosí''s forced laborers extracting Spanish silver; the British East India Company''s Bengal opium monopoly and the wars fought to keep China''s market open to the drug; Queen Victoria''s own opium-soaked Britain — the laudanum-dosed nursery and the Fenland opium-eaters — set against Gladstone''s denunciation of the war his government waged for the trade; Hogarth''s Gin Lane and the class-coded politics of drink from the eighteenth-century gin craze to Prohibition; how race and class, more than pharmacology, built American drug law — Chinese opium dens, the Harrison Act, Anslinger''s marijuana campaign, and the crack-versus-powder sentencing gap; wartime amphetamines and the ''mother''s little helper'' of the 1960s suburbs; and the twenty-first century''s own opium war — Purdue Pharma, the Sackler family, and an opioid epidemic concentrated in the same kind of working communities the nineteenth century''s drug monopolies once supplied. A history, in the end, of who gets to get high, who profits from it, and who gets punished for it.', 27, 1),
  ('history/thematic-history/history-of-civil-liberties', 'history', 'history/thematic-history', 'History of Civil Liberties', 'history-of-civil-liberties', 'How individual freedoms were won, defined, and defended — and repeatedly curtailed: Magna Carta (1215) and habeas corpus; the English Bill of Rights (1689); Enlightenment foundations (Locke, Montesquieu); the US Bill of Rights (1791) and the French Declaration of the Rights of Man and of the Citizen (1789); abolition of slavery; women''s suffrage; the US civil rights movement (Brown v. Board 1954, Civil Rights Act 1964, Voting Rights Act 1965); the Universal Declaration of Human Rights (1948); free speech, press, assembly, religion, due process, and privacy; and the recurring wartime and security-era rollbacks (Alien and Sedition Acts, Japanese American internment, McCarthyism, post-9/11 surveillance) with defenders like the ACLU.', 26, 1),
  ('history/thematic-history/history-of-energy', 'history', 'history/thematic-history', 'History of Energy', 'history-of-energy', 'Civilization as an energy story (Smil): muscle, fire, and biomass; water and wind — the medieval power revolution of mills and sails; the coal transition and why it happened in Britain (Wrigley''s organic-economy escape); steam, railways, and fossil industrialization; oil''s twentieth century and electricity''s transformation of everything; nuclear promise and fear — from Hiroshima to Chernobyl and Fukushima; energy and power in both senses — Mitchell''s Carbon Democracy on coal strikes versus oil''s politics; energy poverty and global inequality; and the renewable transition now underway — solar''s plunge, grids and storage, and whether this transition can be faster than all the ones before.', 12, 1),
  ('history/thematic-history/history-of-peace-and-peacemaking', 'history', 'history/thematic-history', 'History of Peace and Peacemaking', 'history-of-peace-and-peacemaking', 'How wars end and how peace is made and kept: the great peace negotiations after wars — Westphalia (1648), the Congress of Vienna (1814–15) and the balance of power, the Paris Peace Conference (1919) with Wilson''s Fourteen Points and the League of Nations, San Francisco and the UN (1945), and later settlements from Camp David to Dayton and the Good Friday Agreement; and the people who have advocated for peace — not just pacifists but also scientists (the Russell-Einstein Manifesto, Pugwash, Linus Pauling), academics (Galtung''s positive versus negative peace), lawyers (the Hague Conventions, René Cassin and the UDHR, Lemkin), religious leaders (the Quakers, Desmond Tutu, the Dalai Lama), politicians (Wilson, Willy Brandt''s Ostpolitik), freedom fighters and civil rights activists (Gandhi''s satyagraha, Martin Luther King Jr., Mandela); the women''s peace movement (Jane Addams, WILPF) and nuclear disarmament campaigns (CND, the freeze); truth and reconciliation commissions; and peace understood not merely as the absence of war but as social justice and respect for human dignity.', 4, 1),
  ('history/thematic-history/intellectual-history', 'history', 'history/thematic-history', 'intellectual history', 'intellectual-history', '', 3, 1),
  ('history/thematic-history/labor-and-the-political-economy-in-u-s-history', 'history', 'history/thematic-history', 'Labor and the Political Economy in U.S. History', 'labor-and-the-political-economy-in-u-s-history', 'The lives of workers — men and women, slave and free, union and non-union, agricultural, industrial, and service-sector — and how they were shaped by, and how they shaped, economic history: unfree and free labor systems (indentured servitude, slavery, wage labor); industrialization and the factory system; the great labor conflicts — the Railroad Strike of 1877, Haymarket (1886), Homestead (1892), Pullman (1894); the Knights of Labor, the AFL under Samuel Gompers, and the IWW; the Triangle Shirtwaist fire (1911) and Progressive Era reform; the New Deal order — the Wagner Act (1935), the CIO, the Fair Labor Standards Act (1938); Taft-Hartley (1947) and the postwar labor-capital accord; deindustrialization, the PATCO strike (1981), and declining union density; and the running debates over tariffs, antitrust and monopoly, laissez-faire versus regulation, and neoliberalism.', 23, 1),
  ('history/thematic-history/military-history', 'history', 'history/thematic-history', 'military history', 'military-history', 'War as a constant of the modern age — there was a war or other violent conflict somewhere in the world in every single year of the 19th and 20th centuries: the Napoleonic Wars and the Concert of Europe that failed to end war; the century of ''small wars'' — colonial conquests, frontier violence, and imperial policing; Latin America''s independence and interstate wars (including the Paraguayan War, proportionally the deadliest); the Taiping Rebellion, history''s bloodiest civil war; Crimea, the wars of German and Italian unification, and the US Civil War as rehearsals of industrial war; the world wars and total war; and the post-1945 era''s proxy wars, civil wars, and genocides that belie the ''long peace''. Alongside the fighting: military revolutions and technology, conscription and the nation in arms, logistics and economies, the laws of war from the Geneva Conventions onward, and how societies remember and forget their wars.', 2, 1),
  ('history/thematic-history/oil-and-empire', 'history', 'history/thematic-history', 'Oil and Empire', 'oil-and-empire', 'How the political economy of oil has shaped the rise and fall of empires, the fate of nation-states, the making of the economy, the nature of class, gender, and racial discrimination, and the production of historical knowledge and the built urban environment. Empires and states: Churchill''s coal-to-oil navy and Anglo-Persian (1911–14), the post-WWI carve-up of Middle Eastern concessions (the Red Line Agreement, the Seven Sisters, Aramco), oil in the world wars, the Mossadegh coup (1953), OPEC and the 1973 shock, petrodollars, the Carter Doctrine and the Gulf Wars, and the ''resource curse.'' The economy and its people: Rockefeller''s Standard Oil and its breakup; oil labor and class struggle from Baku to the Mexican oil fields; gendered oil towns and petro-masculinity; racial hierarchies in the industry''s segregated camps and company towns (Vitalis''s America''s Kingdom). Knowledge and the city: how company archives and court histories shaped what we know (Yergin''s The Prize versus Mitchell''s Carbon Democracy and the revisionists), and oil''s built environment — Houston and the boomtowns, the automobile suburb, and the car-centric city — down to climate politics and the contested end of oil.', 14, 1),
  ('history/thematic-history/scandals-in-history-moral-panics-repression-and-reform', 'history', 'history/thematic-history', 'Scandals in History: Moral Panics, Repression, and Reform', 'scandals-in-history-moral-panics-repression-and-reform', 'The big scandals in history and how they sparked state repression, political activism, and moral panics — and how, case by case, they drove social change and became a fundamental driver of governance. Organized by theme, showing how individual incidents emerged from and influenced their wider historical contexts, and how scandals illuminate the past: imposture and fraud (the Tichborne claimant); frontier violence (the Myall Creek massacre trials, 1838); urban youth and the larrikin panics; trial by media (the Lindy Chamberlain ''dingo'' case); war crimes (Breaker Morant, 1902; Amritsar, 1919); status anxiety and spies (the Petrov affair, 1954). Anchored in the scandals of Australia and the British imperial world across the nineteenth and twentieth centuries — convict-system exposés, the Governor Eyre controversy after Morant Bay (1865), W. T. Stead''s ''Maiden Tribute of Modern Babylon'' (1885) and the age-of-consent panic, the Wilde trials, Emily Hobhouse and the Boer War camps, the Congo atrocities campaign (Morel, Casement), the Stolen Generations and institutional-abuse royal commissions — but going beyond: the Dreyfus Affair, Teapot Dome, Profumo, Watergate, Iran-Contra, and phone hacking. Each time, tracing the mechanics — investigative journalism, moral panic (Stanley Cohen), commissions of inquiry, and reform legislation — to show how these scandals affected the world.', 19, 1),
  ('history/thematic-history/slavery', 'history', 'history/thematic-history', 'slavery', 'slavery', 'Slavery as a world-historical institution: bondage in the ancient world (Greece, Rome''s slave society); slavery and the medieval worlds — trans-Saharan and Indian Ocean trades, the Islamic world, and the distinction from serfdom; the Atlantic system — the plantation complex, the Middle Passage, and the racialization of slavery; the United States in its hemispheric web — the history of US slavery read against the Haitian Revolution''s shockwaves, the Louisiana Purchase and Indian removal that opened the cotton kingdom, Atlantic cotton and the land and money markets that financed the ''second slavery'', and the hemispheric history of antislavery from Haiti outward; law and life under slavery — family, culture, religion, and everyday resistance; revolt and marronage; abolitionism and the emancipations from Britain (1833) to the US Civil War to Brazil (1888); the afterlives — sharecropping, Jim Crow, and reparations debates; and modern slavery and human trafficking today.', 24, 1),
  ('history/thematic-history/social-history', 'history', 'history/thematic-history', 'social history', 'social-history', 'History from below: how ordinary people — workers, peasants, women, servants, migrants, the poor — lived, worked, married, ate, and died; the field''s revolutions — the Annales school and the longue durée, E. P. Thompson''s The Making of the English Working Class and agency from below, microhistory (Ginzburg''s The Cheese and the Worms); family and demography, childhood, food, housing, leisure, and everyday life; crime and punishment from below; the archives of the inarticulate — parish registers, court records, oral history; and how social history transformed what counts as historical evidence and whose lives count as history.', 1, 1),
  ('history/thematic-history/the-global-history-of-quantitative-data', 'history', 'history/thematic-history', 'The Global History of Quantitative Data', 'the-global-history-of-quantitative-data', 'The global history of quantitative data and the ways numerical reasoning came to shape the nature of knowledge as we know it — from long division to population censuses, standardized testing to the personal computer: cuneiform accounting as writing''s origin; Hindu-Arabic numerals, al-Khwarizmi, and the arithmetic that made calculation teachable; double-entry bookkeeping and merchant capitalism; political arithmetic (Graunt, Petty) and the modern census — from Rome and imperial China to the US census of 1790 and Hollerith''s 1890 punch cards that birthed IBM; probability and statistics — Pascal, Quetelet''s ''average man'', Galton and regression (and the eugenics entanglement), Pearson, Fisher; Hacking''s ''avalanche of numbers'' and Porter''s Trust in Numbers — quantification as objectivity and as politics; standardized testing from Binet and the Army Alpha to the SAT; GDP and national accounts; the computer — Babbage, ENIAC, the personal computer and the spreadsheet; and the present of databases, big data, and algorithmic decision-making, with its debates over surveillance and bias.', 20, 1),
  ('history/thematic-history/the-role-of-infrastructure-in-history-its-powers-and-limitations', 'history', 'history/thematic-history', 'The Role of Infrastructure in History: its Powers and Limitations', 'the-role-of-infrastructure-in-history-its-powers-and-limitations', 'Infrastructure as the skeleton of power and everyday life: the ancient systems — Roman roads and aqueducts, the Persian Royal Road, qanats, and China''s Grand Canal; the industrial age''s networks — the Erie, Suez, and Panama canals, the transcontinental railroads, submarine telegraph cables; sanitation and the public-health revolution (London''s sewers after the Great Stink), electrification, and the American interstate system. Its powers: state-building and ''infrastructural power'' (Michael Mann), empire''s ''tools'' (Headrick), markets made and cities transformed. Its limitations and dark sides: who gets served and who gets bypassed — redlining, Robert Moses''s parkways, splintered cities; legibility''s failures (Scott''s Seeing Like a State); cost overruns, white elephants, deferred maintenance and collapse, path dependence; and the present stakes — the green and digital transitions, China''s buildout versus the West''s gridlock, and infrastructure as geopolitics (Belt and Road).', 13, 1),
  ('history/thematic-history/u-s-foreign-policy', 'history', 'history/thematic-history', 'U.S. Foreign Policy', 'u-s-foreign-policy', 'America''s role in the world from Washington to the present: the Farewell Address and the isolationist inheritance; the Monroe Doctrine (1823); continental expansion and the Mexican War; 1898 and the debate over empire; Wilson, the First World War, and the League fight; from neutrality to the Second World War and the architecture of the liberal order (UN, Bretton Woods, NATO); containment and its wars — Korea and Vietnam; Nixon-Kissinger realpolitik and the opening to China; Reagan and the Cold War''s end; unipolarity, humanitarian intervention, 9/11 and the wars in Afghanistan and Iraq; and the turn to great-power competition with China.', 6, 1),
  ('history/thematic-history/urban-history', 'history', 'history/thematic-history', 'Urban History', 'urban-history', 'The city as history''s great artifact: from Uruk and the first urban revolution through the classical, Islamic, and medieval city; the industrial city''s shock — Manchester, Engels, cholera, and the sanitary reform it forced; planning and its hubris — Haussmann''s Paris, the garden city, Le Corbusier''s modernism, and Jane Jacobs versus Robert Moses; segregation built into space — redlining, ghettos, apartheid urbanism; suburbanization and sprawl; the Global South''s urban century — megacities and informality (Davis''s Planet of Slums); and the questions of the urban age — housing, gentrification, and the climate-adapted city.', 7, 1),
