  ('philosophy/history-of-philosophy/contemporary-thinkers', 'philosophy', 'philosophy/history-of-philosophy', 'contemporary thinkers', 'contemporary-thinkers', '', 7, 1),
  ('philosophy/history-of-philosophy/critical-theory', 'philosophy', 'philosophy/history-of-philosophy', 'Critical Theory', 'critical-theory', 'The Frankfurt School and the tradition of emancipatory critique: the Institute for Social Research (1923) and Horkheimer''s program — theory that aims to liberate, not merely describe; Adorno and Horkheimer''s Dialectic of Enlightenment and the culture industry; Benjamin''s theses on history and the Arcades; Marcuse and the one-dimensional society''s sixties explosion; Fromm; the second generation — Habermas''s communicative turn; the third — Honneth on recognition, Forst on justification; the wider critical family — Foucault''s genealogies, postcolonial critique, critical race theory, feminist critical theory; and the standing question: what grounds critique after the collapse of foundations?', 6, 1),
  ('philosophy/history-of-philosophy/habermas-discourse-ethics-and-communicative-reason-after-metaphysics', 'philosophy', 'philosophy/history-of-philosophy', 'Habermas: Discourse Ethics and Communicative Reason after Metaphysics', 'habermas-discourse-ethics-and-communicative-reason-after-metaphysics', 'Habermas''s attempt to rebuild a pragmatic-transcendentalist theory of ethical and discursive reason after the collapse of metaphysics: postmetaphysical thinking and the linguistic turn from the philosophy of consciousness to communication; The Theory of Communicative Action (1981) — communicative versus strategic action and the validity claims of truth, rightness, and sincerity; universal pragmatics and the quasi-transcendental argument from the unavoidable presuppositions of argumentation (the performative contradiction against the skeptic); discourse ethics — principles (U) and (D) as an intersubjective reconstruction of Kant; the public sphere and deliberative democracy (Between Facts and Norms); and the debates — with Gadamer, Luhmann, Rawls, and the postmodernists — in defense of Enlightenment reason as an ''unfinished project''.', 5, 1),
  ('philosophy/history-of-philosophy/hegel', 'philosophy', 'philosophy/history-of-philosophy', 'Hegel', 'hegel', 'The system-builder of German idealism (1770–1831): the Phenomenology of Spirit (1807) — consciousness''s journey to absolute knowing, the master-slave dialectic, and recognition; dialectic itself — negation, sublation (Aufhebung), and why ''thesis-antithesis-synthesis'' is a caricature; the Science of Logic and the claim that the rational is the real; the Philosophy of Right — freedom actualized in family, civil society, and the state; the philosophy of history — world spirit, the cunning of reason, and history as the progress of the consciousness of freedom (''the owl of Minerva flies at dusk''); art, religion, and philosophy as absolute spirit; the split inheritance — Right Hegelians, Left Hegelians (Feuerbach, the young Marx standing Hegel ''on his head''), Kojève and recognition, Fukuyama''s end of history; and the critics from Kierkegaard to the analytic Hegel revival (Pippin, Brandom).', 3, 1),
  ('philosophy/history-of-philosophy/medieval', 'philosophy', 'philosophy/history-of-philosophy', 'medieval', 'medieval', '', 1, 1),
  ('philosophy/history-of-philosophy/modern', 'philosophy', 'philosophy/history-of-philosophy', 'modern', 'modern', '', 2, 1),
  ('philosophy/history-of-philosophy/nietzsche-s-anti-foundationalist-critique-of-morality-and-truth', 'philosophy', 'philosophy/history-of-philosophy', 'Nietzsche''s Anti-Foundationalist Critique of Morality and Truth', 'nietzsche-s-anti-foundationalist-critique-of-morality-and-truth', 'Nietzsche''s demolition of morality''s and truth''s foundations: the genealogy of morals — master and slave morality, ressentiment, and the ascetic ideal; the death of God (The Gay Science §125) and the specter of European nihilism; perspectivism and ''On Truth and Lies in a Nonmoral Sense'' — truth as ''a mobile army of metaphors''; the critique of Kantian and Christian-Platonic foundations (''how the true world became a fable''); will to power; the revaluation of all values, the Übermensch, and eternal recurrence as affirmative responses; the self-reference problem — whether the critique undermines itself; and the legacy running through existentialism, Foucault''s genealogies, and postmodern thought.', 4, 1),
  ('philosophy/logic/arguments', 'philosophy', 'philosophy/logic', 'arguments', 'arguments', '', 0, 1),
