  ('astronomy-and-space/extragalactic/cosmic-web/intergalactic-medium', 'astronomy-and-space', 'astronomy-and-space/extragalactic/cosmic-web', 'The Intergalactic Medium', 'intergalactic-medium', '', 1, 2),
  ('astronomy-and-space/extragalactic/cosmic-web/large-scale-structure', 'astronomy-and-space', 'astronomy-and-space/extragalactic/cosmic-web', 'Large-Scale Structure', 'large-scale-structure', '', 3, 2),
