  ('economics/macroeconomics/aggregate-output-prices-and-economic-growth/aggregate-demand-and-supply-analysis', 'economics', 'economics/macroeconomics/aggregate-output-prices-and-economic-growth', 'Aggregate Demand and Supply Analysis', 'aggregate-demand-and-supply-analysis', 'Using aggregate demand and aggregate supply to explain the level of output, the price level, inflation, and recessions.', 2, 2),
  ('economics/macroeconomics/aggregate-output-prices-and-economic-growth/aggregate-output-and-income-measurement', 'economics', 'economics/macroeconomics/aggregate-output-prices-and-economic-growth', 'Aggregate Output and Income Measurement', 'aggregate-output-and-income-measurement', 'How a nation''s output and income are measured (GDP and the national income accounts), and why total output equals total income.', 1, 2),
  ('economics/macroeconomics/aggregate-output-prices-and-economic-growth/core-concepts', 'economics', 'economics/macroeconomics/aggregate-output-prices-and-economic-growth', 'Core Concepts', 'core-concepts', 'The core macroeconomic aggregates — output, income, the price level, and growth — and how they fit together.', 0, 2),
  ('economics/macroeconomics/aggregate-output-prices-and-economic-growth/economic-growth-and-its-determinants', 'economics', 'economics/macroeconomics/aggregate-output-prices-and-economic-growth', 'Economic Growth and Its Determinants', 'economic-growth-and-its-determinants', 'What drives long-run economic growth — labor, capital, and productivity — and the factors that sustain or constrain it.', 3, 2),
  ('economics/microeconomics/demand-and-supply-analysis/core-concepts', 'economics', 'economics/microeconomics/demand-and-supply-analysis', 'Core Concepts', 'core-concepts', 'How demand and supply curves determine a market''s equilibrium price and quantity, and what shifts each curve.', 0, 2),
  ('economics/microeconomics/demand-and-supply-analysis/supply-and-demand-for-consumers', 'economics', 'economics/microeconomics/demand-and-supply-analysis', 'Supply and Demand for Consumers', 'supply-and-demand-for-consumers', 'Demand and supply from the individual consumer''s perspective: how consumers respond to prices, income, and preferences, and how their choices aggregate into market demand.', 1, 2),
  ('economics/microeconomics/demand-and-supply-analysis/supply-and-demand-for-firms', 'economics', 'economics/microeconomics/demand-and-supply-analysis', 'Supply and Demand for Firms', 'supply-and-demand-for-firms', 'Demand and supply from the firm''s perspective: how a firm decides how much to produce and supply given its costs and market prices.', 2, 2),
  ('economics/money-and-policy/fiscal-policy/core-concepts', 'economics', 'economics/money-and-policy/fiscal-policy', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('economics/money-and-policy/fiscal-policy/fiscal-policy-objectives', 'economics', 'economics/money-and-policy/fiscal-policy', 'Fiscal Policy Objectives', 'fiscal-policy-objectives', '', 1, 2),
  ('economics/money-and-policy/fiscal-policy/fiscal-policy-tools-and-implementation', 'economics', 'economics/money-and-policy/fiscal-policy', 'Fiscal Policy Tools and Implementation', 'fiscal-policy-tools-and-implementation', '', 2, 2),
  ('economics/money-and-policy/monetary-policy/central-bank-objectives-and-tools', 'economics', 'economics/money-and-policy/monetary-policy', 'Central Bank Objectives and Tools', 'central-bank-objectives-and-tools', '', 1, 2),
  ('economics/money-and-policy/monetary-policy/core-concepts', 'economics', 'economics/money-and-policy/monetary-policy', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('economics/money-and-policy/monetary-policy/monetary-policy-effects-and-limitations', 'economics', 'economics/money-and-policy/monetary-policy', 'Monetary Policy Effects and Limitations', 'monetary-policy-effects-and-limitations', '', 2, 2),
  ('finance/quantitative-foundations/portfolio-mathematics/core-concepts', 'finance', 'finance/quantitative-foundations/portfolio-mathematics', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('finance/quantitative-foundations/portfolio-mathematics/probability-models-for-portfolio-return-and-risk', 'finance', 'finance/quantitative-foundations/portfolio-mathematics', 'Probability Models for Portfolio Return and Risk', 'probability-models-for-portfolio-return-and-risk', 'Calculate and interpret the expected value, variance, standard deviation, covariances, and correlations of portfolio returns.', 1, 2),
  ('finance/quantitative-foundations/probability-trees-and-conditional-expectations/bayes-formula', 'finance', 'finance/quantitative-foundations/probability-trees-and-conditional-expectations', 'Bayes’ Formula', 'bayes-formula', 'Calculate and interpret an updated (posterior) probability in an investment setting using Bayes’ formula.', 3, 2),
  ('finance/quantitative-foundations/probability-trees-and-conditional-expectations/core-concepts', 'finance', 'finance/quantitative-foundations/probability-trees-and-conditional-expectations', 'Core Concepts', 'core-concepts', 'The essentials of probability theory and how it is applied to quantify risk for investment decision-making — probabilities, expected values, and reasoning about uncertain outcomes.', 0, 2),
  ('finance/quantitative-foundations/probability-trees-and-conditional-expectations/expected-values', 'finance', 'finance/quantitative-foundations/probability-trees-and-conditional-expectations', 'Expected Values', 'expected-values', 'Calculate expected values, variances, and standard deviations, and apply them to investment problems.', 2, 2),
  ('finance/quantitative-foundations/probability-trees-and-conditional-expectations/probability-models', 'finance', 'finance/quantitative-foundations/probability-trees-and-conditional-expectations', 'Probability Models', 'probability-models', 'Formulate an investment problem as a probability tree, and explain and apply conditional expectations in an investment setting.', 1, 2),
  ('finance/quantitative-foundations/rates-and-returns/common-measures-of-return', 'finance', 'finance/quantitative-foundations/rates-and-returns', 'Common Measures of Return', 'common-measures-of-return', 'Gross vs net, pre-tax vs after-tax, real, and leveraged returns; annualized return measures (converting a return over any period into a comparable annual figure); and continuously compounded returns and how to compute them.', 3, 2),
  ('finance/quantitative-foundations/rates-and-returns/core-concepts', 'finance', 'finance/quantitative-foundations/rates-and-returns', 'Core Concepts', 'core-concepts', 'What an interest rate is, and the three equivalent ways to read it: as a required rate of return, as a discount rate used to bring future cash flows to the present, and as the opportunity cost of current consumption. An interest rate as the sum of a real risk-free rate plus premiums that compensate investors for bearing distinct types of risk — inflation, default, liquidity, and maturity risk. And how a return is measured over time, including how to calculate it.', 0, 2),
  ('finance/quantitative-foundations/rates-and-returns/interest-rates-and-return-measurement', 'finance', 'finance/quantitative-foundations/rates-and-returns', 'Interest Rates and Return Measurement', 'interest-rates-and-return-measurement', '', 1, 2),
  ('finance/quantitative-foundations/rates-and-returns/time-weighted-and-money-weighted-returns', 'finance', 'finance/quantitative-foundations/rates-and-returns', 'Time-Weighted and Money-Weighted Returns', 'time-weighted-and-money-weighted-returns', 'The money-weighted rate of return (the IRR of a portfolio''s cash flows) and the time-weighted rate of return; how they differ and when each is appropriate; and how to evaluate and compare portfolio performance using these measures — including why time-weighted return is preferred for judging a manager.', 2, 2),
  ('finance/quantitative-foundations/statistical-measures-of-asset-returns/central-tendency-and-dispersion', 'finance', 'finance/quantitative-foundations/statistical-measures-of-asset-returns', 'Central Tendency and Dispersion', 'central-tendency-and-dispersion', 'Calculate, interpret, and evaluate measures of central tendency and location, and measures of dispersion, to address an investment problem.', 1, 2),
  ('finance/quantitative-foundations/statistical-measures-of-asset-returns/core-concepts', 'finance', 'finance/quantitative-foundations/statistical-measures-of-asset-returns', 'Core Concepts', 'core-concepts', 'How descriptive statistics convey the important attributes of return data — measures of central tendency, location, and dispersion — and introduce the characteristics of a return distribution''s shape, including skewness and kurtosis.', 0, 2),
  ('finance/quantitative-foundations/statistical-measures-of-asset-returns/correlation', 'finance', 'finance/quantitative-foundations/statistical-measures-of-asset-returns', 'Correlation', 'correlation', 'Interpret the correlation between two variables to address an investment problem.', 4, 2),
  ('finance/quantitative-foundations/statistical-measures-of-asset-returns/kurtosis', 'finance', 'finance/quantitative-foundations/statistical-measures-of-asset-returns', 'Kurtosis', 'kurtosis', 'Interpret and evaluate the kurtosis of a return distribution to address an investment problem.', 3, 2),
  ('finance/quantitative-foundations/statistical-measures-of-asset-returns/skewness', 'finance', 'finance/quantitative-foundations/statistical-measures-of-asset-returns', 'Skewness', 'skewness', 'Interpret and evaluate the skewness of a return distribution to address an investment problem.', 2, 2),
  ('finance/quantitative-foundations/the-time-value-of-money-in-finance/core-concepts', 'finance', 'finance/quantitative-foundations/the-time-value-of-money-in-finance', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('finance/quantitative-foundations/the-time-value-of-money-in-finance/discounted-cash-flow-valuation', 'finance', 'finance/quantitative-foundations/the-time-value-of-money-in-finance', 'Discounted Cash Flow Valuation', 'discounted-cash-flow-valuation', 'Calculate and interpret the present value (PV) of fixed-income and equity instruments from their expected future cash flows.', 1, 2),
  ('finance/quantitative-foundations/the-time-value-of-money-in-finance/implied-returns-and-cash-flow-additivity', 'finance', 'finance/quantitative-foundations/the-time-value-of-money-in-finance', 'Implied Returns and Cash Flow Additivity', 'implied-returns-and-cash-flow-additivity', 'Calculate and interpret the implied return of fixed-income instruments, and the required return and implied growth rate of equity instruments, given price (PV) and cash flows. Explain the cash flow additivity principle, why it underpins the no-arbitrage condition, and how it is used to compute implied forward interest rates, forward exchange rates, and option values.', 2, 2),
  ('finance/statistical-methods/estimation-and-inference/core-concepts', 'finance', 'finance/statistical-methods/estimation-and-inference', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('finance/statistical-methods/estimation-and-inference/sampling-techniques-and-the-central-limit-theorem', 'finance', 'finance/statistical-methods/estimation-and-inference', 'Sampling Techniques and the Central Limit Theorem', 'sampling-techniques-and-the-central-limit-theorem', '', 1, 2),
  ('finance/statistical-methods/hypothesis-testing/core-concepts', 'finance', 'finance/statistical-methods/hypothesis-testing', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('finance/statistical-methods/hypothesis-testing/hypothesis-testing-basics', 'finance', 'finance/statistical-methods/hypothesis-testing', 'Hypothesis Testing Basics', 'hypothesis-testing-basics', '', 1, 2),
  ('finance/statistical-methods/hypothesis-testing/types-of-hypothesis-tests', 'finance', 'finance/statistical-methods/hypothesis-testing', 'Types of Hypothesis Tests', 'types-of-hypothesis-tests', '', 2, 2),
  ('finance/statistical-methods/introduction-to-big-data-techniques/core-concepts', 'finance', 'finance/statistical-methods/introduction-to-big-data-techniques', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('finance/statistical-methods/introduction-to-big-data-techniques/introduction-to-fintech', 'finance', 'finance/statistical-methods/introduction-to-big-data-techniques', 'Introduction to Fintech', 'introduction-to-fintech', '', 1, 2),
  ('finance/statistical-methods/introduction-to-linear-regression/analysis-of-variance-anova-and-goodness-of-fit', 'finance', 'finance/statistical-methods/introduction-to-linear-regression', 'Analysis of Variance (ANOVA) and Goodness of Fit', 'analysis-of-variance-anova-and-goodness-of-fit', '', 2, 2),
  ('finance/statistical-methods/introduction-to-linear-regression/core-concepts', 'finance', 'finance/statistical-methods/introduction-to-linear-regression', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('finance/statistical-methods/introduction-to-linear-regression/linear-regression-basics', 'finance', 'finance/statistical-methods/introduction-to-linear-regression', 'Linear Regression Basics', 'linear-regression-basics', '', 1, 2),
  ('finance/statistical-methods/introduction-to-linear-regression/predicted-values-and-functional-forms-of-regression', 'finance', 'finance/statistical-methods/introduction-to-linear-regression', 'Predicted Values and Functional Forms of Regression', 'predicted-values-and-functional-forms-of-regression', '', 3, 2),
  ('finance/statistical-methods/parametric-and-non-parametric-tests-of-independence/core-concepts', 'finance', 'finance/statistical-methods/parametric-and-non-parametric-tests-of-independence', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('finance/statistical-methods/parametric-and-non-parametric-tests-of-independence/tests-for-independence', 'finance', 'finance/statistical-methods/parametric-and-non-parametric-tests-of-independence', 'Tests for Independence', 'tests-for-independence', '', 1, 2),
  ('finance/statistical-methods/simulation-methods/core-concepts', 'finance', 'finance/statistical-methods/simulation-methods', 'Core Concepts', 'core-concepts', '', 0, 2),
  ('finance/statistical-methods/simulation-methods/lognormal-distributions-and-simulation-techniques', 'finance', 'finance/statistical-methods/simulation-methods', 'Lognormal Distributions and Simulation Techniques', 'lognormal-distributions-and-simulation-techniques', '', 1, 2),
  ('history/20th-century-history/world-wars/the-first-world-war-ww1', 'history', 'history/20th-century-history/world-wars', 'The First World War (WW1)', 'the-first-world-war-ww1', 'One of the largest and most devastating conflicts the world has ever seen — and one of the first waged across the entire earth, from Europe to Africa, China, and the Middle East: not only a European conflict but a truly global one. Origins — alliance blocs, militarism, imperial rivalry, nationalism, and Sarajevo; course — the Schlieffen Plan''s failure and trench warfare, Verdun and the Somme, with the military and economic aspects of the war in its principal European and Middle Eastern theaters (Gallipoli, the Arab Revolt, Mesopotamia and the Ottoman fronts), plus the campaigns in Africa, the seizure of Qingdao in China, and the empires'' soldiers and laborers from India, Africa, China, and the Pacific; total war economies, blockade, and propaganda; American entry and Russia''s revolutionary exit; legacies — the armistice, Versailles, and four collapsed empires; and how the war transformed conceptions of democracy, the state, gender, race, and art around the world — mass suffrage and welfare states, women''s war work and the vote, colonial veterans and rising anticolonialism, Wilson''s moment in Egypt, India, China, and Korea (1919), and the shattered aesthetics of Dada, the war poets, and modernism. Some 20 million died; the settlement set up the next war.', 0, 2),
  ('history/20th-century-history/world-wars/the-second-world-war-ww2', 'history', 'history/20th-century-history/world-wars', 'The Second World War (WW2)', 'the-second-world-war-ww2', 'The deadliest conflict in history (1939–1945): its origins in Versailles grievances, the Great Depression, fascism and Nazi ideology, appeasement (Munich 1938) and the Molotov-Ribbentrop pact; the invasion of Poland, Blitzkrieg, the fall of France, and the Battle of Britain; Operation Barbarossa and the Eastern Front; Pearl Harbor and the Pacific war; the Holocaust — the systematic murder of six million Jews; the turning points at Stalingrad, Midway, and El Alamein; D-Day and the liberation of Europe; island-hopping, the atomic bombings of Hiroshima and Nagasaki, and Japan''s surrender; Yalta and Potsdam; 70–85 million dead, the founding of the United Nations, and the postwar order that led into the Cold War.', 1, 2),
  ('history/regional-histories/africa/health-and-healing-in-african-history', 'history', 'history/regional-histories/africa', 'Health and Healing in African History', 'health-and-healing-in-african-history', 'Sickness, healing, and the mind in African history: African therapeutic systems — healers and herbalists, divination, spirit possession and ngoma, and their ongoing pluralism alongside biomedicine; witchcraft, causation, and mental health — Evans-Pritchard''s Azande and witchcraft as an explanation of misfortune, accusations and their modern resurgence; colonial medicine and psychiatry — the racialized invention of the ''African mind'', asylums, and Fanon''s critique; substance abuse — khat, cannabis, and alcohol under colonial regulation and after; violence and mental illness — war trauma, child soldiers, and the contested universality of PTSD; and the more recent links between HIV/AIDS, loss, and depression — from denialism to antiretrovirals, orphanhood, and grief — within today''s global mental health debate over universal categories versus local idioms of distress.', 2, 2),
  ('history/regional-histories/africa/history-of-sport-in-africa', 'history', 'history/regional-histories/africa', 'History of Sport in Africa', 'history-of-sport-in-africa', 'Play, power, and the postcolony: indigenous sporting traditions — wrestling, stick-fighting, board games — and their meanings; colonial sport as discipline and ''civilizing'' project, and how Africans made it their own; football''s conquest of the continent — from mission schools to CAF and the Africa Cup of Nations; sport in the liberation struggle — the apartheid sports boycott and South Africa''s isolation, the 1995 Rugby World Cup as reconciliation theater; the runners — Abebe Bikila barefoot in Rome (1960), Kip Keino, and East Africa''s distance dynasty; the 2010 South African World Cup; and the political economy of the player migration to European leagues.', 3, 2),
  ('history/regional-histories/africa/history-of-sub-saharan-africa-to-1860-precolonial-states-and-societies', 'history', 'history/regional-histories/africa', 'History of Sub-Saharan Africa to 1860: Precolonial States and Societies', 'history-of-sub-saharan-africa-to-1860-precolonial-states-and-societies', 'The histories of precolonial states, and Africa on its own terms before the colonial partition, recovered through its rich oral histories — the griots, the Sundiata epic of Mali, and Vansina''s method of reading oral tradition as history — alongside archaeology and written sources: the Bantu migrations; Aksum and early Christian Ethiopia; the Sahelian empires — Ghana, Mali (Mansa Musa, Timbuktu), and Songhai — and the trans-Saharan trade; the Islamic intellectual tradition that flourished in West Africa from the sixteenth century — the Timbuktu manuscript libraries, Sankoré scholarship, Ahmad Baba, and ajami writing; the Swahili coast and the Indian Ocean world; Great Zimbabwe; Kongo, Benin, and the forest kingdoms; the spread of Islam and Christianity; slavery and the slave trades in and from Africa — domestic slavery, the trans-Saharan and Indian Ocean trades, and the Atlantic trade''s demographic and political impact; the nineteenth-century transformations — the Sokoto Caliphate of Usman dan Fodio and the scholar-poet Nana Asma''u, the Zulu kingdom and the mfecane, Omani Zanzibar; and the continent on the eve of European conquest.', 0, 2),
  ('history/regional-histories/africa/modern-african-history-since-1860', 'history', 'history/regional-histories/africa', 'Modern African History since 1860', 'modern-african-history-since-1860', 'The continent from partition to the present: the Scramble for Africa and the Berlin Conference (1884–85); colonial rule and its varieties — direct and indirect rule, settler colonies, Leopold''s Congo; the impact of colonialism in Africa — economic extraction and cash-crop economies, arbitrary borders, missionary education, invented ethnic divisions, and the legacies anatomized by Fanon and Rodney''s How Europe Underdeveloped Africa; resistance from Adwa (1896) to Maji Maji to Mau Mau; Africans in the world wars; the decolonization wave — Ghana (1957), the year of Africa (1960), the Algerian War, the Portuguese wars to 1975; the Congo crisis and Lumumba; apartheid South Africa and the liberation struggle — Sharpeville, Soweto, and Mandela''s 1994 election; post-independence trajectories — nation-building, one-party states and coups, the Cold War''s proxy wars in Angola and the Horn, structural adjustment; the Rwandan genocide (1994); and the twenty-first century — the African Union, demographic boom, mobile-money innovation, and Africa''s contested place in a multipolar world.', 1, 2),
  ('history/regional-histories/africa/women-in-african-history', 'history', 'history/regional-histories/africa', 'Women in African History', 'women-in-african-history', 'African history with women at the center: queens and queen mothers — Amanirenas of Kush who fought Rome, Njinga of Ndongo and Matamba, the Asante queen mothers and Yaa Asantewaa''s war (1900); women''s economic power — the market women of West Africa; women in and against the slave trades; spiritual authority — priestesses, prophets (Kimpa Vita), and spirit mediums (Nehanda); how colonialism eroded women''s institutions — and the resistance it provoked, from the Igbo Women''s War (1929) to anticolonial heroines; nationalist and post-independence leaders — Funmilayo Ransome-Kuti, Ellen Johnson Sirleaf, Wangari Maathai; and the historiographical recovery of women''s voices from sources that tried to erase them.', 4, 2),
  ('history/regional-histories/americas/afro-indigenous-intersections-in-early-america', 'history', 'history/regional-histories/americas', 'Afro-Indigenous Intersections in Early America', 'afro-indigenous-intersections-in-early-america', 'Where African and Native American histories met: Native slavery and the Carolina Indian slave trade alongside African slavery; Africans and Indigenous people intermarrying, allying, and building kin in colonial borderlands; maroon communities and the Black Seminoles; freedom suits that turned on Indigenous ancestry; how settler racial regimes divided the two — blood quantum for Native peoples, the one-drop rule for Black people — and the consequences; slavery within the Five Tribes and the Black freedmen''s citizenship struggles that continue today; and the scholars recovering these entangled histories (Tiya Miles, Kyle Mays).', 1, 2),
  ('history/regional-histories/americas/indigenous-economies-and-environments', 'history', 'history/regional-histories/americas', 'Indigenous Economies and Environments', 'indigenous-economies-and-environments', 'How Indigenous peoples of the Americas shaped and sustained their worlds: land management as science — fire regimes that made the prairies and California''s abundance, clam gardens and salmon stewardship on the Northwest Coast, the buffalo economy of the Plains; agriculture — maize''s domestication, the milpa and Three Sisters, Cahokia''s fields and the Amazon''s terra preta; exchange — continent-spanning trade in obsidian, dentalium, and copper, gift economies and the potlatch; the myth of untouched ''wilderness'' (Cronon, Denevan''s ''pristine myth''); dispossession''s ecological consequences; and the present — traditional ecological knowledge, co-management, and Indigenous-led conservation.', 4, 2),
  ('history/regional-histories/americas/indigenous-oral-literatures-of-the-northwest-coast-of-north-america', 'history', 'history/regional-histories/americas', 'Indigenous Oral Literatures of the Northwest Coast of North America', 'indigenous-oral-literatures-of-the-northwest-coast-of-north-america', 'The great oral literatures of the Haida, Tlingit, Tsimshian, Kwakwaka''wakw, Nuu-chah-nulth, and Coast Salish peoples: the Raven cycle and the trickster''s world-making; crest histories, clan prerogatives, and the oratory of the potlatch; stories as law and title — oral histories admitted as evidence in Delgamuukw v. British Columbia (1997); the tellers and the collectors — Boas and George Hunt''s archive and its colonial entanglements; ethnopoetics (Hymes, Tedlock) and the argument over how to write oral performance; Bringhurst''s Haida translations and the controversy they sparked; Harry Robinson''s told-to narratives; and the living tradition — language revitalization and contemporary Indigenous storytellers carrying the canon forward.', 5, 2),
  ('history/regional-histories/americas/moctezuma-s-mexico', 'history', 'history/regional-histories/americas', 'Moctezuma''s Mexico', 'moctezuma-s-mexico', 'The Aztec world at its height and its catastrophic encounter: Tenochtitlan — the lake city of canals and chinampas that stunned the conquistadors; the Triple Alliance''s tribute empire; Mexica religion, the temple precinct, and the meanings of sacrifice; merchants, markets (Tlatelolco), and everyday life; Moctezuma II — the ruler and the myths later wrapped around him; the conquest — Cortés, La Malinche, the Tlaxcalan alliance, the Noche Triste, smallpox, and the siege of 1521; how we know — the Florentine Codex and Nahua voices alongside Spanish chronicles (León-Portilla''s Broken Spears); and the Aztec afterlife in colonial and modern Mexican identity.', 3, 2),
  ('history/regional-histories/americas/modern-american-history-the-united-states-in-the-twentieth-century', 'history', 'history/regional-histories/americas', 'Modern American History: the United States in the Twentieth Century', 'modern-american-history-the-united-states-in-the-twentieth-century', 'The American century as one arc: the Progressive Era and the First World War''s aftermath; the twenties culture wars — Prohibition, the Scopes trial, the second Klan, the New Woman and the New Negro, nativism and the 1924 quotas; the Crash and the New Deal''s remaking of the American state; World War II at home and abroad — mobilization, the double V, internment; the Cold War at home — McCarthyism, the affluent society, suburbia; the sixties social movements — civil rights, the New Left, feminism, gay liberation, the counterculture, and the backlash; the seventies crisis and the neoliberal turn — Reagan, deregulation, deindustrialization; and the rise of mass incarceration — from the war on crime and the war on drugs to the carceral state (Alexander, Hinton) — closing on the polarized present.', 2, 2),
  ('history/regional-histories/americas/native-american-and-indigenous-studies', 'history', 'history/regional-histories/americas', 'Native American and Indigenous Studies', 'native-american-and-indigenous-studies', 'Indigenous histories of the Americas and the field that studies them: the deep past — Cahokia, the Mesoamerican and Andean civilizations, and the diverse nations of North America; contact, the demographic catastrophe, and the Columbian exchange; settler colonialism as a structure, not an event (Patrick Wolfe); treaties and dispossession — removal and the Trail of Tears, the Plains wars, allotment (Dawes Act), the boarding schools; twentieth-century policy from termination and relocation to self-determination; Red Power — Alcatraz, AIM, and Wounded Knee (1973); sovereignty and treaty rights today — NAGPRA, ICWA, Standing Rock; the global Indigenous movement and UNDRIP (2007); and the field''s methods — oral tradition as evidence, decolonizing methodologies (Linda Tuhiwai Smith), and Indigenous scholars remaking how this history is told.', 0, 2),
  ('history/regional-histories/asia/chinese-history', 'history', 'history/regional-histories/asia', 'Chinese History', 'chinese-history', 'Four thousand years of Chinese history before the modern rupture: Shang oracle bones and the origins of the writing system; the Zhou and the Mandate of Heaven; the hundred schools — Confucius, Laozi, the Legalists; Qin unification and the First Emperor (the terracotta army, the Great Wall''s beginnings); the Han synthesis and the Silk Road; the Tang''s cosmopolitan golden age; the Song commercial and technological revolution — paper money, printing, gunpowder, the compass; the Mongol Yuan and Marco Polo''s China; the Ming — Zheng He''s voyages and the turn inward; the Qing at its height under Kangxi and Qianlong; the machinery of empire — the examination system, the scholar-official, the dynastic cycle; and how this deep past frames China''s modern transformation (continued in Modern China).', 0, 2),
  ('history/regional-histories/asia/han-history', 'history', 'history/regional-histories/asia', 'Han History', 'han-history', 'China''s formative empire (206 BCE–220 CE): from Qin''s collapse to Liu Bang''s founding; Emperor Wu''s expansion and the opening of the Silk Road (Zhang Qian''s missions); the Confucian state — the imperial academy and the beginnings of the examination ideal; Sima Qian''s Records of the Grand Historian, the model for all Chinese history-writing; paper''s invention; Wang Mang''s interregnum and the Eastern Han restoration; court politics — empresses, eunuchs, and the great families; the Yellow Turban revolt and the empire''s dissolution into the Three Kingdoms; and why ''Han'' became the name of the Chinese people themselves.', 1, 2),
  ('history/regional-histories/asia/indochina-and-modern-vietnam-1880s-1980s', 'history', 'history/regional-histories/asia', 'Indochina and Modern Vietnam, 1880s-1980s', 'indochina-and-modern-vietnam-1880s-1980s', 'A century of colonialism and war in Indochina: French rule — rubber and rice, the mission civilisatrice and its contradictions; anticolonial currents and Ho Chi Minh''s road to the Indochinese Communist Party; the Second World War, the Japanese coup, and the famine of 1945; the August Revolution and the First Indochina War — Dien Bien Phu (1954) and Geneva''s partition; the American war (cross-referenced with The Vietnam War); Cambodia''s descent — the Khmer Rouge genocide (1975–79); the Vietnamese invasion of Cambodia and the Sino-Vietnamese war (1979); the boat people; and đổi mới (1986) — modern Vietnam''s turn.', 7, 2),
  ('history/regional-histories/asia/ming-qing-history', 'history', 'history/regional-histories/asia', 'Ming-Qing History', 'ming-qing-history', 'China''s last two dynasties (1368–1912): the Ming founding after the Mongols — the Hongwu autocracy, the Yongle emperor, Zheng He''s ocean voyages and the turn inward, the Great Wall rebuilt; late-Ming commercial efflorescence — silver from the Americas, print culture, the Jiangnan cities; the Manchu conquest of 1644 and the Qing synthesis — banners, the queue, and rule over a multiethnic empire (Tibet, Xinjiang, Mongolia); the High Qing under Kangxi, Yongzheng, and Qianlong; the Jesuits at court; population explosion and its strains; the White Lotus rebellion and dynastic overstretch — setting the stage for the nineteenth century''s crises (continued in Modern China).', 2, 2),
  ('history/regional-histories/asia/modern-south-asia', 'history', 'history/regional-histories/asia', 'Modern South Asia', 'modern-south-asia', 'The subcontinent from the Mughals'' decline to today: East India Company rule and the 1857 Rebellion; the Raj — railways, famines, and the drain debate; the nationalist movement — Congress, Gandhi''s satyagraha, Jinnah and the Muslim League; Partition (1947) and its wounds; Nehru''s India and Pakistan''s turbulent path; the 1971 war and Bangladesh''s birth; Sri Lanka''s civil war; the Emergency; liberalization (1991) and India''s rise; Kashmir, nuclear rivalry, and Hindutva politics — with the diaspora carrying South Asia worldwide.', 4, 2),
  ('history/regional-histories/asia/modern-southeast-asia', 'history', 'history/regional-histories/asia', 'Modern Southeast Asia', 'modern-southeast-asia', 'From colonial patchwork to ASEAN century: the colonial regimes — Dutch East Indies, British Malaya and Burma, French Indochina, the American Philippines, and Siam''s exceptional independence; the Japanese occupation as rupture; the independence struggles and revolutions; the Cold War battleground — Vietnam, the Indonesian massacres of 1965–66, ASEAN''s founding (1967); the tiger economies and the 1997 Asian financial crisis; Suharto, Marcos, and People Power; and the contemporary region — Singapore''s model, Myanmar''s coups, and Southeast Asia between China and the United States.', 5, 2),
  ('history/regional-histories/asia/premodern-korean-history', 'history', 'history/regional-histories/asia', 'Premodern Korean History', 'premodern-korean-history', 'Korea before the modern rupture: Gojoseon and the peninsula''s early states; the Three Kingdoms — Goguryeo, Baekje, Silla — and Silla''s unification with Tang help (668); Goryeo — the celadon age, the Tripitaka Koreana carved against the Mongols, and the world''s first metal movable type; the Joseon dynasty (1392–1897) — Neo-Confucian state-building, King Sejong and the invention of hangul (1443), the yangban aristocracy; the Imjin War — Hideyoshi''s invasions and Admiral Yi Sun-sin''s turtle ships (1592–98); the Manchu invasions and tributary ties to Qing China; the ''hermit kingdom'' and its opening in 1876 — with the deep patterns that still shape both Koreas.', 3, 2),
  ('history/regional-histories/asia/the-modern-history-of-rural-china', 'history', 'history/regional-histories/asia', 'The Modern History of Rural China', 'the-modern-history-of-rural-china', 'The Chinese revolution and reform as the countryside lived them: the rural crisis of the republican era and why the CCP won the villages; land reform and the destruction of the landlord class; collectivization, the people''s communes, and the Great Leap famine''s rural devastation; the hukou system and the rural-urban divide it entrenched; the household responsibility system and the reform era''s village boom (township and village enterprises); the great migration — 300 million migrant workers and the left-behind villages; rural taxation revolts, land grabs, and protest; and the poverty-alleviation and rural-revitalization campaigns of the Xi era.', 6, 2),
  ('history/regional-histories/europe/east-european-identities-russia-and-ukraine', 'history', 'history/regional-histories/europe', 'East European Identities: Russia and Ukraine', 'east-european-identities-russia-and-ukraine', 'Two nations and a contested inheritance: Kyivan Rus and the rival claims to its legacy; Cossack Ukraine and the Hetmanate; imperial Russification and the Ukrainian national revival of the nineteenth century; revolution and short-lived independence (1917–21); Soviet Ukrainization reversed by the Holodomor (1932–33); the bloodlands of the Second World War (Snyder); 1991 and the divergent post-Soviet paths; the Orange Revolution and the Maidan (2014); Crimea and the Donbas; the full-scale invasion of 2022; and the war over history itself — Putin''s ''historical unity'' essay versus Plokhy and the Ukrainian historians.', 0, 2),
  ('history/regional-histories/europe/god-save-the-queen-the-british-monarchy', 'history', 'history/regional-histories/europe', 'God Save the Queen: the British Monarchy', 'god-save-the-queen-the-british-monarchy', 'How the British monarchy survived the age of revolutions and everything since: the constitutional bargain of 1688 and Bagehot''s ''dignified'' crown; Victoria and the imperial monarchy — Empress of India, the invention of royal tradition; the world wars and the Windsors'' rebranding; the abdication crisis (1936); Elizabeth II''s seven decades — the Commonwealth, decolonization''s managed retreat, Diana and the near-death of deference, devolution and republicanism (Australia''s 1999 referendum); Charles III; and the anthem''s double life — from national hymn to the Sex Pistols'' 1977 detonation of it.', 2, 2),
  ('history/regional-histories/europe/the-european-union', 'history', 'history/regional-histories/europe', 'The European Union', 'the-european-union', 'The improbable union: from the Schuman Declaration and the Coal and Steel Community (1951) through the Treaty of Rome (1957), the single market, and Maastricht (1992); the euro and its flawed architecture; the great eastward enlargement of 2004; how the institutions work — Commission, Council, Parliament, Court — and the democratic-deficit debate; the crisis decade — the eurozone and Greece, the 2015 migration crisis, Brexit; the EU as peace project versus neoliberal machine; and today''s questions — enlargement to Ukraine, strategic autonomy, and the union''s place between the US and China.', 1, 2),
  ('history/regional-histories/middle-east/a-history-of-modern-syria', 'history', 'history/regional-histories/middle-east', 'A History of Modern Syria', 'a-history-of-modern-syria', 'Syria from Ottoman province to shattered and remade state: greater Syria under the Ottomans; the French mandate — partition into statelets and the Great Revolt of 1925; independence (1946) and the coup-ridden decades; the Ba''th, the union with Egypt, and 1963; Hafez al-Assad''s Syria — the security state, the Muslim Brotherhood uprising and Hama (1982); Bashar and the false spring; 2011 — the uprising and its descent into civil war; the actors — the regime and its Russian and Iranian patrons, the opposition, ISIS and the caliphate, the Kurds; barrel bombs, chemical attacks, and half the population displaced; the fall of the Assad regime in December 2024 and the uncertain transition since — with a century''s lessons about minority rule, sectarianism, and outside powers.', 1, 2),
  ('history/regional-histories/middle-east/jerusalem-a-history-from-antiquity-to-the-present', 'history', 'history/regional-histories/middle-east', 'Jerusalem, a History: From Antiquity to the Present', 'jerusalem-a-history-from-antiquity-to-the-present', 'One city, three faiths, four thousand years: Bronze Age origins and the city David took; Solomon''s Temple, the Babylonian destruction (586 BCE) and exile; the Second Temple, Herod''s rebuilding, and Rome''s destruction of it (70 CE); Aelia Capitolina; Byzantine Christian Jerusalem and the Holy Sepulchre; the Islamic conquest, the Dome of the Rock and al-Aqsa; the Crusader kingdom and Saladin''s reconquest; Mamluk and Ottoman centuries (Suleiman''s walls); British Mandate Jerusalem; 1948 and the divided city; 1967 and the contested unification; and the present — holy sites, sovereignty claims, and why Jerusalem remains the hardest question of the Israeli-Palestinian conflict (Montefiore''s biography of the city as anchor text).', 2, 2),
  ('history/regional-histories/middle-east/the-making-of-the-modern-middle-east', 'history', 'history/regional-histories/middle-east', 'The Making of the Modern Middle East', 'the-making-of-the-modern-middle-east', 'How the region''s modern map and politics were made: late Ottoman reform and collapse; the First World War''s triple promises — Sykes-Picot, the Balfour Declaration, the McMahon correspondence; the mandates and state-building in Iraq, Syria, Lebanon, Transjordan, and Palestine; oil and the making of the Gulf; Israel''s founding and the Nakba (1948); Nasser, pan-Arabism, and Suez (1956); the wars of 1967 and 1973; Iran''s 1979 revolution; Lebanon''s civil war; the Gulf wars, Oslo and its collapse, the Arab Spring and its aftermath — and the patterns connecting a century of intervention, authoritarianism, and resistance.', 0, 2),
  ('mathematics/core-graduate/advanced-complex-analysis/harmonic-functions-and-riemann-mapping', 'mathematics', 'mathematics/core-graduate/advanced-complex-analysis', 'Harmonic Functions & the Riemann Mapping Theorem', 'harmonic-functions-and-riemann-mapping', 'Harmonic functions and conformal equivalence.', 0, 2),
  ('mathematics/core-graduate/advanced-complex-analysis/riemann-surfaces', 'mathematics', 'mathematics/core-graduate/advanced-complex-analysis', 'Riemann Surfaces', 'riemann-surfaces', 'Analytic continuation, and the Weierstrass and Hadamard product formulas.', 1, 2),
